1	#!/usr/bin/env node
2	/**
3	 * 메이플 파티 결성 보드 — 넥슨 Open API 조회 프로토타입 v2
4	 *
5	 * v2 변경점: 전투력 대표값 로직 개선
6	 *  - 최대 전투력 기록 시 당시 착용 장비 구성(해시)을 함께 저장
7	 *  - 갱신 시 현재 장비 프리셋 1/2/3 + 착용 구성과 대조:
8	 *      · 저장된 구성이 존재 → 세팅 유지 중 → 최대치 유지 (드메템 착용과 무관)
9	 *      · 어디에도 없음     → 세팅 변경됨 → 최대치 무효화, 현재 값으로 재설정
10	 *
11	 * 사용법
12	 *  export NEXON_API_KEY=발급받은키
13	 *  node maple-proto.js char 알전임    # 조회 + 전투력/세팅 기록
14	 *  node maple-proto.js log 알전임     # 기록 확인
15	 *  node maple-proto.js my-list       # 내 계정 캐릭터 목록 (키 소유 계정 한정)
16	 */
17	
18	const fs = require("fs");
19	const path = require("path");
20	const crypto = require("crypto");
21	
22	const BASE = "https://open.api.nexon.com";
23	const API_KEY = process.env.NEXON_API_KEY;
24	const LOG_FILE = path.join(__dirname, "power_log.json");
25	
26	// ---------- API 호출 공통 ----------
27	
28	async function nx(endpoint, params = {}) {
29	  const qs = new URLSearchParams(params).toString();
30	  const url = `${BASE}${endpoint}${qs ? "?" + qs : ""}`;
31	  const res = await fetch(url, { headers: { "x-nxopen-api-key": API_KEY } });
32	  const body = await res.json();
33	  if (!res.ok) {
34	    const msg = body?.error?.message || res.statusText;
35	    const name = body?.error?.name || res.status;
36	    throw new Error(`[${name}] ${msg} (${endpoint})`);
37	  }
38	  return body;
39	}
40	
41	const getOcid = async (name) =>
42	  (await nx("/maplestory/v1/id", { character_name: name })).ocid;
43	const getBasic = (ocid) => nx("/maplestory/v1/character/basic", { ocid });
44	const getEquipment = (ocid) => nx("/maplestory/v1/character/item-equipment", { ocid });
45	const getMyCharacterList = () => nx("/maplestory/v1/character/list");
46	const getScheduler = (ocid, date) =>
47	  nx("/maplestory/v1/scheduler/character-state", date ? { ocid, date } : { ocid });
48	
49	async function getCombatPower(ocid) {
50	  const stat = await nx("/maplestory/v1/character/stat", { ocid });
51	  const row = (stat.final_stat || []).find((s) => s.stat_name === "전투력");
52	  return row ? Number(row.stat_value) : null;
53	}
54	
55	// ---------- 장비 구성 해시 ----------
56	// 전투력에 영향을 주는 필드만 추려서 해시. 외형/캐시 요소는 제외해
57	// 코디 변경으로 무효화가 오발동하지 않게 한다.
58	
59	function normalizeItem(it) {
60	  return {
61	    slot: it.item_equipment_slot,
62	    name: it.item_name,
63	    star: it.starforce ?? "0",
64	    total: it.item_total_option ?? null, // 주문서+스타포스 반영 최종 수치
65	    pot: [it.potential_option_grade, it.potential_option_1, it.potential_option_2, it.potential_option_3],
66	    add: [it.additional_potential_option_grade, it.additional_potential_option_1, it.additional_potential_option_2, it.additional_potential_option_3],
67	    soul: it.soul_name ?? null,
68	  };
69	}
70	
71	function hashItemList(list) {
72	  const norm = (list || [])
73	    .map(normalizeItem)
74	    .sort((a, b) => (a.slot > b.slot ? 1 : -1));
75	  return crypto.createHash("sha1").update(JSON.stringify(norm)).digest("hex").slice(0, 16);
76	}
77	
78	/** 착용 + 프리셋 1/2/3 각각의 구성 해시 */
79	function setupHashes(equip) {
80	  return {
81	    equipped: hashItemList(equip.item_equipment),
82	    p1: hashItemList(equip.item_equipment_preset_1),
83	    p2: hashItemList(equip.item_equipment_preset_2),
84	    p3: hashItemList(equip.item_equipment_preset_3),
85	  };
86	}
87	
88	// ---------- 로그 저장소 ----------
89	// { [ocid]: { name, entries: [{ts, power}],
90	//             best: { power, ts, setupHash } | null } }
91	
92	function loadLog() {
93	  try { return JSON.parse(fs.readFileSync(LOG_FILE, "utf8")); } catch { return {}; }
94	}
95	function saveLog(log) {
96	  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2));
97	}
98	
99	// ---------- 대표 전투력 갱신 로직 (핵심) ----------
100	
101	function updateBest(rec, power, hashes) {
102	  const now = new Date().toISOString();
103	  let note = null;
104	
105	  // 1) 기존 최대치의 세팅이 아직 존재하는지 검사
106	  if (rec.best) {
107	    const alive = Object.values(hashes).includes(rec.best.setupHash);
108	    if (!alive) {
109	      note = `세팅 변경 감지 → 기존 최대치 ${rec.best.power.toLocaleString()} 무효화, 현재 값으로 재설정`;
110	      rec.best = null;
111	    }
112	  }
113	
114	  // 2) 최대치 갱신 (무효화됐다면 현재 관측값이 새 기준이 됨)
115	  if (!rec.best || power > rec.best.power) {
116	    rec.best = { power, ts: now, setupHash: hashes.equipped };
117	    if (!note) note = "최대 전투력 갱신";
118	  }
119	
120	  rec.entries.push({ ts: now, power });
121	  return note;
122	}
123	
124	// ---------- 출력 유틸 ----------
125	
126	function fmtPower(n) {
127	  if (n == null) return "-";
128	  if (n >= 100_000_000) {
129	    const eok = Math.floor(n / 100_000_000);
130	    const man = Math.floor((n % 100_000_000) / 10_000);
131	    return man > 0 ? `${eok}억 ${man}만` : `${eok}억`;
132	  }
133	  if (n >= 10_000) return `${Math.floor(n / 10_000)}만`;
134	  return String(n);
135	}
136	
137	// ---------- 커맨드 ----------
138	
139	async function cmdChar(name) {
140	  const ocid = await getOcid(name);
141	  const [basic, power, equip] = await Promise.all([
142	    getBasic(ocid), getCombatPower(ocid), getEquipment(ocid),
143	  ]);
144	  const hashes = setupHashes(equip);
145	
146	  const log = loadLog();
147	  if (!log[ocid]) log[ocid] = { name: basic.character_name, entries: [], best: null };
148	  const rec = log[ocid];
149	  rec.name = basic.character_name;
150	  const note = updateBest(rec, power, hashes);
151	  saveLog(log);
152	
153	  const wearingBest = hashes.equipped === rec.best.setupHash;
154	  console.log(`\n${basic.character_name}  (${basic.world_name} · ${basic.character_class} · Lv.${basic.character_level})`);
155	  console.log(`  대표 전투력 : ${fmtPower(rec.best.power)} (${rec.best.ts.slice(0, 10)} 기준)`);
156	  console.log(`  현재 측정값 : ${fmtPower(power)}${wearingBest ? "" : "  ※ 대표값과 다른 세팅 착용 중"}`);
157	  if (note) console.log(`  변경 사항   : ${note}`);
158	  console.log(`  maplescouter: https://maplescouter.com/ko/result?name=${encodeURIComponent(basic.character_name)}`);
159	  console.log("");
160	}
161	
162	async function cmdLog(name) {
163	  const log = loadLog();
164	  const rec = Object.values(log).find((c) => c.name === name);
165	  if (!rec) return console.log(`기록 없음: ${name} — 먼저 'char ${name}' 로 조회하세요.`);
166	  console.log(`\n${rec.name} — 대표 전투력 ${fmtPower(rec.best?.power)} (${rec.best?.ts.slice(0, 10)} 기준)`);
167	  for (const e of rec.entries.slice(-10)) {
168	    console.log(`  ${e.ts.slice(0, 16).replace("T", " ")}  ${fmtPower(e.power)}`);
169	  }
170	  console.log("");
171	}
172	
173	async function cmdSched(name, date) {
174	  const ocid = await getOcid(name);
175	  const s = await getScheduler(ocid, date);
176	  if (!s) return console.log("스케줄러 데이터 없음 (최근 14일 내 접속 기록이 없을 수 있음)");
177	
178	  console.log(`\n${s.character_name} 스케줄러 (기준일: ${s.date ?? "실시간"})`);
179	  console.log(`  주간 보스: ${s.weekly_boss_clear_count} / ${s.weekly_boss_clear_limit_count} 클리어\n`);
180	
181	  const bosses = (s.boss_contents || []).sort((a, b) => a.list_order_no - b.list_order_no);
182	  for (const b of bosses) {
183	    const done = String(b.complete_flag) === "true" ? "✅" : "⬜";
184	    const reg = String(b.registration_flag) === "true" ? "" : " (스케줄러 미등록)";
185	    console.log(`  ${done} [${b.cycle}] ${b.content_name} · ${b.difficulty}${reg}`);
186	  }
187	
188	  const weekly = (s.weekly_contents || []).filter((c) => c.type === "contents");
189	  if (weekly.length) {
190	    console.log("\n  주간 콘텐츠:");
191	    for (const w of weekly) console.log(`    ${w.content_name}: ${w.now_count}/${w.max_count}`);
192	  }
193	  console.log("");
194	}
195	
196	async function cmdMyList() {
197	  const { account_list } = await getMyCharacterList();
198	  for (const acc of account_list || []) {
199	    console.log(`\n계정 ${acc.account_id}`);
200	    for (const c of acc.character_list || []) {
201	      console.log(`  ${c.character_name}  (${c.world_name} · ${c.character_class} · Lv.${c.character_level})`);
202	    }
203	  }
204	  console.log("");
205	}
206	
207	// ---------- 엔트리 ----------
208	
209	(async () => {
210	  if (!API_KEY) {
211	    console.error("NEXON_API_KEY 환경변수를 설정하세요. (https://openapi.nexon.com 에서 발급)");
212	    process.exit(1);
213	  }
214	  const [cmd, arg] = process.argv.slice(2);
215	  try {
216	    const arg2 = process.argv[4];
217	    if (cmd === "char" && arg) await cmdChar(arg);
218	    else if (cmd === "log" && arg) await cmdLog(arg);
219	    else if (cmd === "sched" && arg) await cmdSched(arg, arg2);
220	    else if (cmd === "my-list") await cmdMyList();
221	    else {
222	      console.log("사용법:");
223	      console.log("  node maple-proto.js char <닉네임>          조회 + 전투력/세팅 기록");
224	      console.log("  node maple-proto.js log <닉네임>           기록 확인");
225	      console.log("  node maple-proto.js sched <닉네임> [날짜]   보스 클리어/스케줄러 조회 (날짜: YYYY-MM-DD, 최근 13일까지)");
226	      console.log("  node maple-proto.js my-list               내 계정 캐릭터 목록");
227	    }
228	  } catch (e) {
229	    console.error("오류:", e.message);
230	    process.exit(1);
231	  }
232	})();
