    if (cmd === "char" && arg) await cmdChar(arg);
    else if (cmd === "log" && arg) await cmdLog(arg);
    else if (cmd === "sched" && arg) await cmdSched(arg, arg2);
    else if (cmd === "my-list") await cmdMyList();
    else {
      console.log("사용법:");
