// 등록(registration_flag) 과 클리어(complete_flag) 가 독립인지 실측:
//  - 미등록인데 클리어된 행 존재 여부
//  - 같은 보스 안에서 등록 난이도 != 클리어 난이도 케이스
const fs = require("fs");
const src = fs.readFileSync("C:/Users/SSAFY/Downloads/maple-proto.js", "utf8");
const KEY = src.match(/"(test_[a-f0-9]+)"/)[1];
const BASE = "https://open.api.nexon.com";
const H = { "x-nxopen-api-key": KEY };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function nx(ep, params = {}) {
  const qs = new URLSearchParams(params).toString();
  const res = await fetch(`${BASE}${ep}${qs ? "?" + qs : ""}`, { headers: H });
  return { ok: res.ok, body: await res.json() };
}

(async () => {
  const list = (await nx("/maplestory/v1/character/list")).body.account_list.flatMap((a) => a.character_list);
  const targets = list.filter((c) => c.character_level >= 250).map((c) => c.character_name);
  console.log("대상:", targets.join(", "));
  for (const n of targets) {
    await sleep(250);
    const id = await nx("/maplestory/v1/id", { character_name: n });
