// ---------- 주간 결정 90개 최적 배분 ----------
//
// 모델 (사용자 가정): "노말 스우 이상을 잡는 캐릭터는 그 아래를 모두 잡을 수 있다"
//   → 캐릭터마다 '상한 보스'(실측 클리어 중 결정 가격 최고)를 두고,
//     상한 가격 이하인 모든 (보스, 난이도)를 클리어 가능으로 본다. 난이도 순서 = 가격 순서.
// 제약:
//   · 캐릭터당 주간 보스 클리어 한도 (weekly_boss_clear_limit_count, 기본 12)
//   · 캐릭터·보스 조합당 난이도 1개
//   · 월드당 주간 결정 판매 한도 (기본 90) — 일간/월간 결정은 한도 밖
// 제약이 (캐릭터·보스) ⊂ 캐릭터 ⊂ 월드 로 중첩(laminar)이라 가격 내림차순 그리디가 최적.
//
// 상한 산정: 어제 + 지난주 마지막 날(수요일) 스케줄러 스냅샷에서 complete_flag=true 인 주간 보스 중 최고가.
// 수동 보정: plan_overrides.json  { "닉": { "ceiling": "선택받은 세렌 hard" } | { "skip": true } }

const PLAN_OVERRIDE_FILE = path.join(__dirname, "plan_overrides.json");

function kstDateStr(offsetDays = 0) {
  return new Date(Date.now() + 9 * 3600e3 + offsetDays * 864e5).toISOString().slice(0, 10);
}
/** 지난주 마지막 날(수요일) — 주간 리셋은 목요일 00:00 KST */
function lastWednesdayKst() {
  const now = new Date(Date.now() + 9 * 3600e3);
  const sinceThu = (now.getUTCDay() - 4 + 7) % 7; // 이번 주 목요일로부터 며칠 지났나
  return kstDateStr(-(sinceThu + 1));
}

/** 가격표에서 주간 보스 후보 (보스, 난이도, 가격) 전체. weeklySet 이 있으면 그것으로 필터. */
function weeklyCandidates(priceDate, weeklySet) {
  const out = [];
  for (const [boss, diffs] of Object.entries(PRICE_TABLE.prices || {})) {
    for (const diff of Object.keys(diffs)) {
      if (weeklySet && !weeklySet.has(`${boss}|${diff}`)) continue;
      const p = crystalPrice(boss, diff, priceDate);
      if (p != null) out.push({ boss, diff, price: p });
    }
  }
  return out;
}

async function cmdPlan(opts) {
  const limit = opts.limit ?? 90;
  const priceDate = opts.date ?? kstDateStr();
  const minLevel = opts.minLevel ?? 235; // 노말 스우 입장 190이지만 결정 수익 의미 있는 구간만
  const overrides = (() => { try { return JSON.parse(fs.readFileSync(PLAN_OVERRIDE_FILE, "utf8")); } catch { return {}; } })();
  const snapDates = [...new Set([kstDateStr(-1), lastWednesdayKst()])];

  const { account_list } = await getMyCharacterList();
  const chars = (account_list || []).flatMap((a) => a.character_list || [])
    .filter((c) => c.character_level >= minLevel && !overrides[c.character_name]?.skip);
  console.log(`\n대상 캐릭터 ${chars.length}명 (Lv.${minLevel}+), 스냅샷 ${snapDates.join(", ")}, 가격 기준 ${priceDate}, 월드 한도 ${limit}개`);

  const weeklySet = new Set();
  const profiles = []; // { name, world, cap, ceiling: {boss,diff,price} | null, cleared: Set }
  for (const c of chars) {
    await sleep(220);
    let ocid;
    try { ocid = await getOcid(c.character_name); } catch { profiles.push({ ...c, err: "ocid 실패" }); continue; }
    let cap = 12, best = null;
    const cleared = new Map();
    for (const d of snapDates) {
      await sleep(220);
      let s;
      try { s = await getScheduler(ocid, d); } catch { continue; }
      if (s.weekly_boss_clear_limit_count) cap = s.weekly_boss_clear_limit_count;
      for (const b of s.boss_contents || []) {
        if (b.cycle === "bossWeekly") weeklySet.add(`${b.content_name}|${b.difficulty}`);
        if (b.cycle !== "bossWeekly" || String(b.complete_flag) !== "true") continue;
        const p = crystalPrice(b.content_name, b.difficulty, priceDate);
        cleared.set(`${b.content_name}|${b.difficulty}`, p);
        if (p != null && (!best || p > best.price)) best = { boss: b.content_name, diff: b.difficulty, price: p };
      }
    }
    const ov = overrides[c.character_name]?.ceiling;
    if (ov) {
      const [boss, diff] = ov.split(/\s+/);
      const p = crystalPrice(boss, diff, priceDate);
      if (p != null) best = { boss, diff, price: p, manual: true };
    }
    profiles.push({ name: c.character_name, world: c.world_name, level: c.character_level, cls: c.character_class, cap, ceiling: best, clearedCount: cleared.size });
    process.stdout.write(".");
  }
  console.log("");

  const candidates = weeklyCandidates(priceDate, weeklySet.size ? weeklySet : null);
  if (!candidates.length) return console.log("주간 보스 가격 데이터 없음");

  // 월드별 그리디
  const byWorld = {};
  for (const p of profiles) (byWorld[p.world ?? "?"] ??= []).push(p);

  for (const [world, list] of Object.entries(byWorld)) {
    const usable = list.filter((p) => p.ceiling);
    const unknown = list.filter((p) => !p.ceiling);
    console.log(`\n══════ ${world} ══════`);
    if (!usable.length) { console.log("  상한 파악된 캐릭터 없음"); continue; }

    // 캐릭터별 후보: 보스마다 상한 가격 이하 최고 난이도 1개
    const pool = [];
    for (const p of usable) {
      const bestPerBoss = {};
      for (const c of candidates) {
        if (c.price > p.ceiling.price) continue;
        if (!bestPerBoss[c.boss] || c.price > bestPerBoss[c.boss].price) bestPerBoss[c.boss] = c;
      }
      for (const c of Object.values(bestPerBoss)) pool.push({ char: p, ...c });
    }
    pool.sort((a, b) => b.price - a.price);

    const perChar = new Map(usable.map((p) => [p.name, []]));
    let total = 0, count = 0;
    for (const item of pool) {
      if (count >= limit) break;
      const picks = perChar.get(item.char.name);
      if (picks.length >= item.char.cap) continue;
      picks.push(item); total += item.price; count++;
    }

    const ranked = usable
      .map((p) => ({ p, picks: perChar.get(p.name), sum: perChar.get(p.name).reduce((s, x) => s + x.price, 0) }))
      .filter((r) => r.picks.length)
      .sort((a, b) => b.sum - a.sum);
    for (const { p, picks, sum } of ranked) {
      const tag = p.ceiling.manual ? "수동" : `실측 ${p.clearedCount}클`;
      console.log(`\n  ${p.name} (${p.cls} Lv.${p.level}) 상한 ${p.ceiling.boss} ${p.ceiling.diff} [${tag}] — ${picks.length}개 ${fmtPower(sum)}`);
      for (const x of picks) console.log(`      ${x.boss} · ${x.diff}  ${fmtPower(x.price)}`);
    }
    const idle = usable.filter((p) => !perChar.get(p.name).length).map((p) => p.name);
    console.log(`\n  ▶ ${world} 합계: 결정 ${count}/${limit}개, ${fmtPower(total)}`);
    if (count < limit) console.log(`  ※ 한도 미달 ${limit - count}개 — 캐릭터 추가 또는 상한 상향 필요`);
    if (idle.length) console.log(`  ※ 배분 0개 (상위 캐릭터가 한도 소진): ${idle.join(", ")}`);
    if (unknown.length) console.log(`  ※ 상한 미파악(최근 클리어 이력 없음): ${unknown.map((p) => p.name).join(", ")} — plan_overrides.json 으로 지정 가능`);
  }
  console.log("");
}

