// 자동 후보: 상한 이하 보스마다 최고 난이도 1개, 고정 픽에 이미 있는 보스는 제외. 정렬 기준은 실수령(가격 ÷ 인원).
const pool = [];
for (const p of list) {
  if (!p.auto || !p.ceiling) continue;
  const fixedBosses = new Set(p.fixed.map((f) => f.boss));
  const bestPerBoss = {};
  for (const c of candidates) {
    if (c.price > p.ceiling.price || fixedBosses.has(c.boss)) continue;
    // 익스트림은 가격이 낮아도 난이도가 별개 축이라 "가격 이하 = 가능" 가정을 적용하지 않음.
    if (c.diff === "extreme" && !p.cleared.has(`${c.boss}|${c.diff}`) && !(p.ceiling.boss === c.boss && p.ceiling.diff === c.diff)) continue;
    if (!bestPerBoss[c.boss] || c.price > bestPerBoss[c.boss].price) bestPerBoss[c.boss] = c;
  }
  for (const c of Object.values(bestPerBoss)) pool.push({ char: p, ...c, party: p.party, value: Math.floor(c.price / p.party) });
}

