/**
 * 보스 키 표기 유틸.
 * "진 힐라 hard" 처럼 보스명(공백 허용) + 마지막 토큰이 난이도인 문자열을 다룬다.
 */

export type Difficulty = "easy" | "normal" | "hard" | "chaos" | "extreme";
export const DIFFICULTIES: Difficulty[] = ["easy", "normal", "hard", "chaos", "extreme"];

export interface BossRef {
  boss: string;
  diff: Difficulty;
}

export function bossKey(boss: string, diff: string): string {
  return `${boss} ${diff}`;
}

/** "진 힐라 hard" → { boss: "진 힐라", diff: "hard" }. 형식이 틀리면 null. */
export function parseBossKey(str: string): BossRef | null {
  const s = String(str ?? "").trim();
  const cut = s.lastIndexOf(" ");
  if (cut < 0) return null;
  const boss = s.slice(0, cut).trim();
  const diff = s.slice(cut + 1) as Difficulty;
  if (!boss || !DIFFICULTIES.includes(diff)) return null;
  return { boss, diff };
}

export interface BossListEntry {
  key: string;
  party: number | null;
  raw: unknown;
}

/**
 * bosses 세 가지 표기를 [{key, party, raw}] 로 통일:
 *   배열-문자열  ["진 힐라 hard"]
 *   배열-객체    [{ boss: "진 힐라 hard", party: 2 }]
 *   객체(맵)     { "진 힐라 hard": 2 }   ← 권장. 값 = 인원
 */
export function normalizeBossList(bosses: unknown): BossListEntry[] {
  if (!bosses) return [];
  if (Array.isArray(bosses)) {
    return bosses.map((raw) => {
      if (typeof raw === "string") return { key: raw, party: null, raw };
      const o = (raw ?? {}) as { boss?: string; party?: number };
      return { key: String(o.boss ?? ""), party: o.party ?? null, raw };
    });
  }
  if (typeof bosses === "object") {
    return Object.entries(bosses as Record<string, unknown>).map(([key, party]) => ({
      key,
      party: typeof party === "number" ? party : Number(party) || null,
      raw: { [key]: party },
    }));
  }
  return [];
}

/**
 * 결정석 가격표 (src/data/boss_crystal_prices.json).
 * entry 형식 A: { old, new, new_from }  — new_from(YYYY-MM-DD)부터 new 적용
 * entry 형식 B: { price }               — 변경 이력 없음
 * null: 가격 미확인
 *
 * 표의 값은 솔로(1인) 판매가. 실수령 = 가격 ÷ 파티 인원.
 */
import raw from "@/data/boss_crystal_prices.json";
import type { Difficulty } from "./bossKey";

type ChangeEntry = { old: number; new: number; new_from: string };
type FixedEntry = { price: number };
export type PriceEntry = ChangeEntry | FixedEntry | null;

export interface PriceTable {
  _meta: {
    updated?: string;
    sources?: string[];
    notes?: string[];
    weekly_world_sale_limit?: number | null;
    difficulty_map?: Record<string, string>;
  };
  prices: Record<string, Partial<Record<Difficulty, PriceEntry>>>;
}

export const PRICE_TABLE = raw as unknown as PriceTable;

/** 기준일(YYYY-MM-DD)에 유효한 결정석 가격. 미확인이면 null. */
export function crystalPrice(boss: string, diff: string, dateISO: string): number | null {
  const entry = PRICE_TABLE.prices?.[boss]?.[diff as Difficulty];
  if (!entry) return null;
  if ("price" in entry) return entry.price;
  if (entry.new_from && dateISO >= entry.new_from) return entry.new;
  return entry.old ?? null;
}

export interface Candidate {
  boss: string;
  diff: Difficulty;
  price: number;
}

/** 가격표 전체 후보 (보스, 난이도, 가격). weeklySet("boss|diff")이 있으면 그것으로 필터. */
export function weeklyCandidates(priceDate: string, weeklySet?: Set<string> | null): Candidate[] {
  const out: Candidate[] = [];
  for (const [boss, diffs] of Object.entries(PRICE_TABLE.prices ?? {})) {
    for (const diff of Object.keys(diffs) as Difficulty[]) {
      if (weeklySet && !weeklySet.has(`${boss}|${diff}`)) continue;
      const p = crystalPrice(boss, diff, priceDate);
      if (p != null) out.push({ boss, diff, price: p });
    }
  }
  return out;
}

/** 가격 변경 시점 목록 (기준일 토글용). 오름차순, 중복 제거. */
export function priceChangeDates(): string[] {
  const set = new Set<string>();
  for (const diffs of Object.values(PRICE_TABLE.prices ?? {})) {
    for (const e of Object.values(diffs)) {
      if (e && "new_from" in e) set.add(e.new_from);
    }
  }
  return [...set].sort();
}

/**
 * 보스 티어 (src/data/boss_tiers.json, 나무위키 기준).
 * 등급 = 색(금>은>동>납) + 별 개수. rank 는 1(납★)~32(금★★★★★★★★★).
 * 상한 판정은 가격이 아닌 티어로: 상한 rank 이하의 (보스, 난이도)만 클리어 가능으로 본다.
 */
import raw from "@/data/boss_tiers.json";

export type Grade = "금" | "은" | "동" | "납";
export interface Tier {
  grade: Grade;
  stars: number;
  rank: number;
}

interface TierFile {
  _meta?: unknown;
  tiers: Record<Grade, Record<string, string[]>>;
  rank_base: Record<Grade, number>;
}

const file = raw as unknown as TierFile;

export const TIER_MAP: Record<string, Tier> = (() => {
  const map: Record<string, Tier> = {};
  for (const [grade, stars] of Object.entries(file.tiers ?? {}) as [Grade, Record<string, string[]>][]) {
    for (const [n, list] of Object.entries(stars)) {
      for (const key of list) {
        map[key] = { grade, stars: Number(n), rank: (file.rank_base?.[grade] ?? 0) + Number(n) };
      }
    }
  }
  return map;
})();

export function tierOf(boss: string, diff: string): Tier | null {
  return TIER_MAP[`${boss} ${diff}`] ?? null;
}

export function tierLabel(t: Tier | null | undefined): string {
  return t ? `${t.grade}★${t.stars}` : "티어없음";
}

/** 티어표 전체 키를 rank 내림차순으로 (상한 드롭다운용). */
export function tierKeysByRank(): { key: string; tier: Tier }[] {
  return Object.entries(TIER_MAP)
    .map(([key, tier]) => ({ key, tier }))
    .sort((a, b) => b.tier.rank - a.tier.rank);
}

/** 메소/전투력 한국식 축약. 1억 5692만, 8960만, 404만, 999 */
export function fmtPower(n: number | null | undefined): string {
  if (n == null) return "-";
  if (n >= 100_000_000) {
    const eok = Math.floor(n / 100_000_000);
    const man = Math.floor((n % 100_000_000) / 10_000);
    return man > 0 ? `${eok}억 ${man}만` : `${eok}억`;
  }
  if (n >= 10_000) return `${Math.floor(n / 10_000)}만`;
  return String(n);
}

export const fmtMeso = fmtPower;

/** 3자리 콤마 */
export function fmtNum(n: number | null | undefined): string {
  if (n == null) return "-";
  return n.toLocaleString("ko-KR");
}

/**
 * KST 날짜 유틸. 메이플 주간 리셋은 목요일 00:00 KST.
 * 날짜 문자열은 항상 "YYYY-MM-DD".
 */

const KST_OFFSET_MS = 9 * 3600e3;
const DAY_MS = 864e5;

/** 오늘(KST) 기준 offsetDays 만큼 이동한 날짜 문자열 */
export function kstDateStr(offsetDays = 0, now: number = Date.now()): string {
  return new Date(now + KST_OFFSET_MS + offsetDays * DAY_MS).toISOString().slice(0, 10);
}

/** "YYYY-MM-DD" → 그 날짜의 요일 (0=일 … 4=목) */
export function dayOfWeek(dateStr: string): number {
  return new Date(`${dateStr}T00:00:00Z`).getUTCDay();
}

/** "YYYY-MM-DD" 에 days 더하기 */
export function addDays(dateStr: string, days: number): string {
  return new Date(new Date(`${dateStr}T00:00:00Z`).getTime() + days * DAY_MS).toISOString().slice(0, 10);
}

/** 해당 날짜가 속한 주의 시작(목요일) 날짜 */
export function weekStartOf(dateStr: string): string {
  const sinceThu = (dayOfWeek(dateStr) - 4 + 7) % 7;
  return addDays(dateStr, -sinceThu);
}

/** 지난주 마지막 날(수요일). 오늘이 목요일이면 어제. */
export function lastWednesdayKst(now: number = Date.now()): string {
  return addDays(weekStartOf(kstDateStr(0, now)), -1);
}

/** 이번 주 시작(목요일) */
export function thisWeekStartKst(now: number = Date.now()): string {
  return weekStartOf(kstDateStr(0, now));
}

/**
 * 전투력 대표값 로직.
 * - 최대 전투력 기록 시 당시 착용 장비 구성(해시)을 함께 저장
 * - 갱신 시 현재 장비 프리셋 1/2/3 + 착용 구성과 대조:
 *     · 저장된 구성이 어디든 존재 → 세팅 유지 중 → 최대치 유지 (드메템 착용과 무관)
 *     · 어디에도 없음           → 세팅 변경됨 → 최대치 무효화, 현재 값으로 재설정
 * 외형/캐시 요소는 해시에서 제외해 코디 변경으로 오발동하지 않게 한다.
 */
import { createHash } from "node:crypto";

export interface EquipItem {
  item_equipment_slot?: string;
  item_name?: string;
  starforce?: string;
  item_total_option?: unknown;
  potential_option_grade?: string | null;
  potential_option_1?: string | null;
  potential_option_2?: string | null;
  potential_option_3?: string | null;
  additional_potential_option_grade?: string | null;
  additional_potential_option_1?: string | null;
  additional_potential_option_2?: string | null;
  additional_potential_option_3?: string | null;
  soul_name?: string | null;
  [k: string]: unknown;
}

export interface EquipmentResponse {
  item_equipment?: EquipItem[];
  item_equipment_preset_1?: EquipItem[];
  item_equipment_preset_2?: EquipItem[];
  item_equipment_preset_3?: EquipItem[];
  [k: string]: unknown;
}

export interface SetupHashes {
  equipped: string;
  p1: string;
  p2: string;
  p3: string;
}

export interface BestRecord {
  power: number;
  ts: string;
  setupHash: string;
}

export interface PowerRecord {
  name?: string;
  entries: { ts: string; power: number }[];
  best: BestRecord | null;
}

function normalizeItem(it: EquipItem) {
  return {
    slot: it.item_equipment_slot,
    name: it.item_name,
    star: it.starforce ?? "0",
    total: it.item_total_option ?? null,
    pot: [it.potential_option_grade, it.potential_option_1, it.potential_option_2, it.potential_option_3],
    add: [
      it.additional_potential_option_grade,
      it.additional_potential_option_1,
      it.additional_potential_option_2,
      it.additional_potential_option_3,
    ],
    soul: it.soul_name ?? null,
  };
}

export function hashItemList(list: EquipItem[] | undefined | null): string {
  const norm = (list ?? []).map(normalizeItem).sort((a, b) => ((a.slot ?? "") > (b.slot ?? "") ? 1 : -1));
  return createHash("sha1").update(JSON.stringify(norm)).digest("hex").slice(0, 16);
}

/** 착용 + 프리셋 1/2/3 각각의 구성 해시 */
export function setupHashes(equip: EquipmentResponse): SetupHashes {
  return {
    equipped: hashItemList(equip.item_equipment),
    p1: hashItemList(equip.item_equipment_preset_1),
    p2: hashItemList(equip.item_equipment_preset_2),
    p3: hashItemList(equip.item_equipment_preset_3),
  };
}

export type BestUpdateNote = "invalidated" | "new_best" | null;

export interface BestUpdateResult {
  best: BestRecord;
  note: BestUpdateNote;
  /** 무효화된 경우 이전 최대치 */
  previousBest?: BestRecord;
}

/**
 * 대표 전투력 갱신. rec 를 변경하지 않고 결과를 반환한다.
 * power 가 null 이면 기록만 남기지 않고 기존 best 유지.
 */
export function updateBest(
  prevBest: BestRecord | null,
  power: number,
  hashes: SetupHashes,
  now: string = new Date().toISOString(),
): BestUpdateResult {
  let best = prevBest;
  let note: BestUpdateNote = null;
  let previousBest: BestRecord | undefined;

  // 1) 기존 최대치의 세팅이 아직 존재하는지 검사
  if (best) {
    const alive = Object.values(hashes).includes(best.setupHash);
    if (!alive) {
      previousBest = best;
      best = null;
      note = "invalidated";
    }
  }

  // 2) 최대치 갱신 (무효화됐다면 현재 관측값이 새 기준이 됨)
  if (!best || power > best.power) {
    best = { power, ts: now, setupHash: hashes.equipped };
    if (!note) note = "new_best";
  }

  return { best, note, previousBest };
}

/**
 * 스케줄러 API 응답 파싱 + 결정 수익 추정.
 * 실측 사실:
 *  - boss_contents 행 목록은 고정이 아님(등록 상태에 따라 56→80행). 있는 행만 다룬다.
 *  - registration_flag 와 complete_flag 는 행 단위로 독립. 수익/상한은 complete_flag 만 쓴다.
 *  - quest_state 는 "0"/"1"/"2" 문자열. 0=미완료, 1=진행중, 2=완료 (관측 기반 추정).
 */
import type { Difficulty } from "./bossKey";
import { crystalPrice } from "./prices";
import { tierOf, type Tier } from "./tiers";

export type BossCycle = "bossDaily" | "bossWeekly" | "bossMonthly";

export interface RawBossRow {
  content_name: string;
  difficulty: string;
  cycle: string;
  registration_flag: string | boolean;
  complete_flag: string | boolean;
  list_order_no?: number;
}

export interface RawContentRow {
  content_name: string;
  type: "contents" | "quest" | string;
  registration_flag: string | boolean;
  now_count: number;
  max_count: number;
  quest_state: string | null;
}

export interface RawScheduler {
  date: string | null;
  character_name: string;
  world_name: string;
  character_level: number;
  character_class: string;
  daily_contents?: RawContentRow[];
  weekly_contents?: RawContentRow[];
  boss_contents?: RawBossRow[];
  weekly_boss_clear_count: number;
  weekly_boss_clear_limit_count: number;
}

export interface BossClearRow {
  boss: string;
  diff: Difficulty;
  cycle: BossCycle;
  registered: boolean;
  completed: boolean;
  order: number;
  tier: Tier | null;
}

export interface ContentRow {
  name: string;
  kind: "contents" | "quest";
  registered: boolean;
  now: number;
  max: number;
  /** quest 전용 */
  questState: "todo" | "progress" | "done" | "unknown" | null;
}

export interface ParsedSnapshot {
  date: string | null;
  name: string;
  world: string;
  level: number;
  cls: string;
  weeklyClearCount: number;
  weeklyLimit: number;
  bosses: BossClearRow[];
  daily: ContentRow[];
  weekly: ContentRow[];
}

const T = (v: unknown) => String(v) === "true";

function parseContent(c: RawContentRow): ContentRow {
  const kind = c.type === "quest" ? "quest" : "contents";
  let questState: ContentRow["questState"] = null;
  if (kind === "quest") {
    questState = ({ "0": "todo", "1": "progress", "2": "done" } as const)[String(c.quest_state)] ?? "unknown";
  }
  return { name: c.content_name, kind, registered: T(c.registration_flag), now: c.now_count ?? 0, max: c.max_count ?? 0, questState };
}

export function parseSnapshot(raw: RawScheduler): ParsedSnapshot {
  const bosses: BossClearRow[] = (raw.boss_contents ?? [])
    .map((b) => ({
      boss: b.content_name,
      diff: b.difficulty as Difficulty,
      cycle: b.cycle as BossCycle,
      registered: T(b.registration_flag),
      completed: T(b.complete_flag),
      order: b.list_order_no ?? 0,
      tier: tierOf(b.content_name, b.difficulty),
    }))
    .sort((a, b) => a.order - b.order);
  return {
    date: raw.date ?? null,
    name: raw.character_name,
    world: raw.world_name,
    level: raw.character_level,
    cls: raw.character_class,
    weeklyClearCount: raw.weekly_boss_clear_count ?? 0,
    weeklyLimit: raw.weekly_boss_clear_limit_count ?? 12,
    bosses,
    daily: (raw.daily_contents ?? []).map(parseContent),
    weekly: (raw.weekly_contents ?? []).map(parseContent),
  };
}

export interface RevenueLine {
  boss: string;
  diff: Difficulty;
  cycle: BossCycle;
  price: number | null;
  party: number;
  /** price ÷ party (floor). price null 이면 null */
  value: number | null;
}

export interface RevenueSummary {
  lines: RevenueLine[];
  byCycle: Record<BossCycle, { count: number; gross: number; value: number }>;
  totalGross: number;
  totalValue: number;
  unpriced: string[];
}

/**
 * 클리어된 보스의 결정 수익 추정. 등록 여부와 무관하게 completed 기준.
 * partyOf(boss, diff) 로 인원 지정. 없으면 1인(솔로).
 */
export function estimateRevenue(
  bosses: BossClearRow[],
  priceDate: string,
  partyOf: (boss: string, diff: string) => number = () => 1,
): RevenueSummary {
  const byCycle: RevenueSummary["byCycle"] = {
    bossDaily: { count: 0, gross: 0, value: 0 },
    bossWeekly: { count: 0, gross: 0, value: 0 },
    bossMonthly: { count: 0, gross: 0, value: 0 },
  };
  const lines: RevenueLine[] = [];
  const unpriced: string[] = [];
  for (const b of bosses) {
    if (!b.completed) continue;
    const price = crystalPrice(b.boss, b.diff, priceDate);
    const party = Math.max(1, partyOf(b.boss, b.diff) || 1);
    const value = price == null ? null : Math.floor(price / party);
    lines.push({ boss: b.boss, diff: b.diff, cycle: b.cycle, price, party, value });
    const c = byCycle[b.cycle] ?? (byCycle[b.cycle] = { count: 0, gross: 0, value: 0 });
    c.count++;
    if (price == null) unpriced.push(`${b.boss} ${b.diff}`);
    else {
      c.gross += price;
      c.value += value!;
    }
  }
  const totalGross = Object.values(byCycle).reduce((s, c) => s + c.gross, 0);
  const totalValue = Object.values(byCycle).reduce((s, c) => s + c.value, 0);
  return { lines, byCycle, totalGross, totalValue, unpriced };
}

/** 실측 클리어 중 티어 최고 행 (상한 산정용). 티어 미배정 보스는 제외. */
export function highestClearedTier(bosses: BossClearRow[]): BossClearRow | null {
  let best: BossClearRow | null = null;
  for (const b of bosses) {
    if (!b.completed || b.cycle !== "bossWeekly" || !b.tier) continue;
    if (!best || b.tier.rank > best.tier!.rank) best = b;
  }
  return best;
}

toolUseResult.content:
/**
 * 보스 키 표기 유틸.
 * "진 힐라 hard" 처럼 보스명(공백 허용) + 마지막 토큰이 난이도인 문자열을 다룬다.
 */

export type Difficulty = "easy" | "normal" | "hard" | "chaos" | "extreme";
export const DIFFICULTIES: Difficulty[] = ["easy", "normal", "hard", "chaos", "extreme"];

export interface BossRef {
  boss: string;
  diff: Difficulty;
}

export function bossKey(boss: string, diff: string): string {
  return `${boss} ${diff}`;
}

/** "진 힐라 hard" → { boss: "진 힐라", diff: "hard" }. 형식이 틀리면 null. */
export function parseBossKey(str: string): BossRef | null {
  const s = String(str ?? "").trim();
  const cut = s.lastIndexOf(" ");
  if (cut < 0) return null;
  const boss = s.slice(0, cut).trim();
  const diff = s.slice(cut + 1) as Difficulty;
  if (!boss || !DIFFICULTIES.includes(diff)) return null;
  return { boss, diff };
}

export interface BossListEntry {
  key: string;
  party: number | null;
  raw: unknown;
}

/**
 * bosses 세 가지 표기를 [{key, party, raw}] 로 통일:
 *   배열-문자열  ["진 힐라 hard"]
 *   배열-객체    [{ boss: "진 힐라 hard", party: 2 }]
 *   객체(맵)     { "진 힐라 hard": 2 }   ← 권장. 값 = 인원
 */
export function normalizeBossList(bosses: unknown): BossListEntry[] {
  if (!bosses) return [];
  if (Array.isArray(bosses)) {
    return bosses.map((raw) => {
      if (typeof raw === "string") return { key: raw, party: null, raw };
      const o = (raw ?? {}) as { boss?: string; party?: number };
      return { key: String(o.boss ?? ""), party: o.party ?? null, raw };
    });
  }
  if (typeof bosses === "object") {
    return Object.entries(bosses as Record<string, unknown>).map(([key, party]) => ({
      key,
      party: typeof party === "number" ? party : Number(party) || null,
      raw: { [key]: party },
    }));
  }
  return [];
}

/**
 * 결정석 가격표 (src/data/boss_crystal_prices.json).
 * entry 형식 A: { old, new, new_from }  — new_from(YYYY-MM-DD)부터 new 적용
 * entry 형식 B: { price }               — 변경 이력 없음
 * null: 가격 미확인
 *
 * 표의 값은 솔로(1인) 판매가. 실수령 = 가격 ÷ 파티 인원.
 */
import raw from "@/data/boss_crystal_prices.json";
import type { Difficulty } from "./bossKey";

type ChangeEntry = { old: number; new: number; new_from: string };
type FixedEntry = { price: number };
export type PriceEntry = ChangeEntry | FixedEntry | null;

export interface PriceTable {
  _meta: {
    updated?: string;
    sources?: string[];
    notes?: string[];
    weekly_world_sale_limit?: number | null;
    difficulty_map?: Record<string, string>;
  };
  prices: Record<string, Partial<Record<Difficulty, PriceEntry>>>;
}

export const PRICE_TABLE = raw as unknown as PriceTable;

/** 기준일(YYYY-MM-DD)에 유효한 결정석 가격. 미확인이면 null. */
export function crystalPrice(boss: string, diff: string, dateISO: string): number | null {
  const entry = PRICE_TABLE.prices?.[boss]?.[diff as Difficulty];
  if (!entry) return null;
  if ("price" in entry) return entry.price;
  if (entry.new_from && dateISO >= entry.new_from) return entry.new;
  return entry.old ?? null;
}

export interface Candidate {
  boss: string;
  diff: Difficulty;
  price: number;
}

/** 가격표 전체 후보 (보스, 난이도, 가격). weeklySet("boss|diff")이 있으면 그것으로 필터. */
export function weeklyCandidates(priceDate: string, weeklySet?: Set<string> | null): Candidate[] {
  const out: Candidate[] = [];
  for (const [boss, diffs] of Object.entries(PRICE_TABLE.prices ?? {})) {
    for (const diff of Object.keys(diffs) as Difficulty[]) {
      if (weeklySet && !weeklySet.has(`${boss}|${diff}`)) continue;
      const p = crystalPrice(boss, diff, priceDate);
      if (p != null) out.push({ boss, diff, price: p });
    }
  }
  return out;
}

/** 가격 변경 시점 목록 (기준일 토글용). 오름차순, 중복 제거. */
export function priceChangeDates(): string[] {
  const set = new Set<string>();
  for (const diffs of Object.values(PRICE_TABLE.prices ?? {})) {
    for (const e of Object.values(diffs)) {
      if (e && "new_from" in e) set.add(e.new_from);
    }
  }
  return [...set].sort();
}

/**
 * 보스 티어 (src/data/boss_tiers.json, 나무위키 기준).
 * 등급 = 색(금>은>동>납) + 별 개수. rank 는 1(납★)~32(금★★★★★★★★★).
 * 상한 판정은 가격이 아닌 티어로: 상한 rank 이하의 (보스, 난이도)만 클리어 가능으로 본다.
 */
import raw from "@/data/boss_tiers.json";

export type Grade = "금" | "은" | "동" | "납";
export interface Tier {
  grade: Grade;
  stars: number;
  rank: number;
}

interface TierFile {
  _meta?: unknown;
  tiers: Record<Grade, Record<string, string[]>>;
  rank_base: Record<Grade, number>;
}

const file = raw as unknown as TierFile;

export const TIER_MAP: Record<string, Tier> = (() => {
  const map: Record<string, Tier> = {};
  for (const [grade, stars] of Object.entries(file.tiers ?? {}) as [Grade, Record<string, string[]>][]) {
    for (const [n, list] of Object.entries(stars)) {
      for (const key of list) {
        map[key] = { grade, stars: Number(n), rank: (file.rank_base?.[grade] ?? 0) + Number(n) };
      }
    }
  }
  return map;
})();

export function tierOf(boss: string, diff: string): Tier | null {
  return TIER_MAP[`${boss} ${diff}`] ?? null;
}

export function tierLabel(t: Tier | null | undefined): string {
  return t ? `${t.grade}★${t.stars}` : "티어없음";
}

/** 티어표 전체 키를 rank 내림차순으로 (상한 드롭다운용). */
export function tierKeysByRank(): { key: string; tier: Tier }[] {
  return Object.entries(TIER_MAP)
    .map(([key, tier]) => ({ key, tier }))
    .sort((a, b) => b.tier.rank - a.tier.rank);
}

/** 메소/전투력 한국식 축약. 1억 5692만, 8960만, 404만, 999 */
export function fmtPower(n: number | null | undefined): string {
  if (n == null) return "-";
  if (n >= 100_000_000) {
    const eok = Math.floor(n / 100_000_000);
    const man = Math.floor((n % 100_000_000) / 10_000);
    return man > 0 ? `${eok}억 ${man}만` : `${eok}억`;
  }
  if (n >= 10_000) return `${Math.floor(n / 10_000)}만`;
  return String(n);
}

export const fmtMeso = fmtPower;

/** 3자리 콤마 */
export function fmtNum(n: number | null | undefined): string {
  if (n == null) return "-";
  return n.toLocaleString("ko-KR");
}

/**
 * KST 날짜 유틸. 메이플 주간 리셋은 목요일 00:00 KST.
 * 날짜 문자열은 항상 "YYYY-MM-DD".
 */

const KST_OFFSET_MS = 9 * 3600e3;
const DAY_MS = 864e5;

/** 오늘(KST) 기준 offsetDays 만큼 이동한 날짜 문자열 */
export function kstDateStr(offsetDays = 0, now: number = Date.now()): string {
  return new Date(now + KST_OFFSET_MS + offsetDays * DAY_MS).toISOString().slice(0, 10);
}

/** "YYYY-MM-DD" → 그 날짜의 요일 (0=일 … 4=목) */
export function dayOfWeek(dateStr: string): number {
  return new Date(`${dateStr}T00:00:00Z`).getUTCDay();
}

/** "YYYY-MM-DD" 에 days 더하기 */
export function addDays(dateStr: string, days: number): string {
  return new Date(new Date(`${dateStr}T00:00:00Z`).getTime() + days * DAY_MS).toISOString().slice(0, 10);
}

/** 해당 날짜가 속한 주의 시작(목요일) 날짜 */
export function weekStartOf(dateStr: string): string {
  const sinceThu = (dayOfWeek(dateStr) - 4 + 7) % 7;
  return addDays(dateStr, -sinceThu);
}

/** 지난주 마지막 날(수요일). 오늘이 목요일이면 어제. */
export function lastWednesdayKst(now: number = Date.now()): string {
  return addDays(weekStartOf(kstDateStr(0, now)), -1);
}

/** 이번 주 시작(목요일) */
export function thisWeekStartKst(now: number = Date.now()): string {
  return weekStartOf(kstDateStr(0, now));
}

/**
 * 전투력 대표값 로직.
 * - 최대 전투력 기록 시 당시 착용 장비 구성(해시)을 함께 저장
 * - 갱신 시 현재 장비 프리셋 1/2/3 + 착용 구성과 대조:
 *     · 저장된 구성이 어디든 존재 → 세팅 유지 중 → 최대치 유지 (드메템 착용과 무관)
 *     · 어디에도 없음           → 세팅 변경됨 → 최대치 무효화, 현재 값으로 재설정
 * 외형/캐시 요소는 해시에서 제외해 코디 변경으로 오발동하지 않게 한다.
 */
import { createHash } from "node:crypto";

export interface EquipItem {
  item_equipment_slot?: string;
  item_name?: string;
  starforce?: string;
  item_total_option?: unknown;
  potential_option_grade?: string | null;
  potential_option_1?: string | null;
  potential_option_2?: string | null;
  potential_option_3?: string | null;
  additional_potential_option_grade?: string | null;
  additional_potential_option_1?: string | null;
  additional_potential_option_2?: string | null;
  additional_potential_option_3?: string | null;
  soul_name?: string | null;
  [k: string]: unknown;
}

export interface EquipmentResponse {
  item_equipment?: EquipItem[];
  item_equipment_preset_1?: EquipItem[];
  item_equipment_preset_2?: EquipItem[];
  item_equipment_preset_3?: EquipItem[];
  [k: string]: unknown;
}

export interface SetupHashes {
  equipped: string;
  p1: string;
  p2: string;
  p3: string;
}

export interface BestRecord {
  power: number;
  ts: string;
  setupHash: string;
}

export interface PowerRecord {
  name?: string;
  entries: { ts: string; power: number }[];
  best: BestRecord | null;
}

function normalizeItem(it: EquipItem) {
  return {
    slot: it.item_equipment_slot,
    name: it.item_name,
    star: it.starforce ?? "0",
    total: it.item_total_option ?? null,
    pot: [it.potential_option_grade, it.potential_option_1, it.potential_option_2, it.potential_option_3],
    add: [
      it.additional_potential_option_grade,
      it.additional_potential_option_1,
      it.additional_potential_option_2,
      it.additional_potential_option_3,
    ],
    soul: it.soul_name ?? null,
  };
}

export function hashItemList(list: EquipItem[] | undefined | null): string {
  const norm = (list ?? []).map(normalizeItem).sort((a, b) => ((a.slot ?? "") > (b.slot ?? "") ? 1 : -1));
  return createHash("sha1").update(JSON.stringify(norm)).digest("hex").slice(0, 16);
}

/** 착용 + 프리셋 1/2/3 각각의 구성 해시 */
export function setupHashes(equip: EquipmentResponse): SetupHashes {
  return {
    equipped: hashItemList(equip.item_equipment),
    p1: hashItemList(equip.item_equipment_preset_1),
    p2: hashItemList(equip.item_equipment_preset_2),
    p3: hashItemList(equip.item_equipment_preset_3),
  };
}

export type BestUpdateNote = "invalidated" | "new_best" | null;

export interface BestUpdateResult {
  best: BestRecord;
  note: BestUpdateNote;
  /** 무효화된 경우 이전 최대치 */
  previousBest?: BestRecord;
}

/**
 * 대표 전투력 갱신. rec 를 변경하지 않고 결과를 반환한다.
 * power 가 null 이면 기록만 남기지 않고 기존 best 유지.
 */
export function updateBest(
  prevBest: BestRecord | null,
  power: number,
  hashes: SetupHashes,
  now: string = new Date().toISOString(),
): BestUpdateResult {
  let best = prevBest;
  let note: BestUpdateNote = null;
  let previousBest: BestRecord | undefined;

  // 1) 기존 최대치의 세팅이 아직 존재하는지 검사
  if (best) {
    const alive = Object.values(hashes).includes(best.setupHash);
    if (!alive) {
      previousBest = best;
      best = null;
      note = "invalidated";
    }
  }

  // 2) 최대치 갱신 (무효화됐다면 현재 관측값이 새 기준이 됨)
  if (!best || power > best.power) {
    best = { power, ts: now, setupHash: hashes.equipped };
    if (!note) note = "new_best";
  }

  return { best, note, previousBest };
}

/**
 * 스케줄러 API 응답 파싱 + 결정 수익 추정.
 * 실측 사실:
 *  - boss_contents 행 목록은 고정이 아님(등록 상태에 따라 56→80행). 있는 행만 다룬다.
 *  - registration_flag 와 complete_flag 는 행 단위로 독립. 수익/상한은 complete_flag 만 쓴다.
 *  - quest_state 는 "0"/"1"/"2" 문자열. 0=미완료, 1=진행중, 2=완료 (관측 기반 추정).
 */
import type { Difficulty } from "./bossKey";
import { crystalPrice } from "./prices";
import { tierOf, type Tier } from "./tiers";

export type BossCycle = "bossDaily" | "bossWeekly" | "bossMonthly";

export interface RawBossRow {
  content_name: string;
  difficulty: string;
  cycle: string;
  registration_flag: string | boolean;
  complete_flag: string | boolean;
  list_order_no?: number;
}

export interface RawContentRow {
  content_name: string;
  type: "contents" | "quest" | string;
  registration_flag: string | boolean;
  now_count: number;
  max_count: number;
  quest_state: string | null;
}

export interface RawScheduler {
  date: string | null;
  character_name: string;
  world_name: string;
  character_level: number;
  character_class: string;
  daily_contents?: RawContentRow[];
  weekly_contents?: RawContentRow[];
  boss_contents?: RawBossRow[];
  weekly_boss_clear_count: number;
  weekly_boss_clear_limit_count: number;
}

export interface BossClearRow {
  boss: string;
  diff: Difficulty;
  cycle: BossCycle;
  registered: boolean;
  completed: boolean;
  order: number;
  tier: Tier | null;
}

export interface ContentRow {
  name: string;
  kind: "contents" | "quest";
  registered: boolean;
  now: number;
  max: number;
  /** quest 전용 */
  questState: "todo" | "progress" | "done" | "unknown" | null;
}

export interface ParsedSnapshot {
  date: string | null;
  name: string;
  world: string;
  level: number;
  cls: string;
  weeklyClearCount: number;
  weeklyLimit: number;
  bosses: BossClearRow[];
  daily: ContentRow[];
  weekly: ContentRow[];
}

const T = (v: unknown) => String(v) === "true";

function parseContent(c: RawContentRow): ContentRow {
  const kind = c.type === "quest" ? "quest" : "contents";
  let questState: ContentRow["questState"] = null;
  if (kind === "quest") {
    questState = ({ "0": "todo", "1": "progress", "2": "done" } as const)[String(c.quest_state)] ?? "unknown";
  }
  return { name: c.content_name, kind, registered: T(c.registration_flag), now: c.now_count ?? 0, max: c.max_count ?? 0, questState };
}

export function parseSnapshot(raw: RawScheduler): ParsedSnapshot {
  const bosses: BossClearRow[] = (raw.boss_contents ?? [])
    .map((b) => ({
      boss: b.content_name,
      diff: b.difficulty as Difficulty,
      cycle: b.cycle as BossCycle,
      registered: T(b.registration_flag),
      completed: T(b.complete_flag),
      order: b.list_order_no ?? 0,
      tier: tierOf(b.content_name, b.difficulty),
    }))
    .sort((a, b) => a.order - b.order);
  return {
    date: raw.date ?? null,
    name: raw.character_name,
    world: raw.world_name,
    level: raw.character_level,
    cls: raw.character_class,
    weeklyClearCount: raw.weekly_boss_clear_count ?? 0,
    weeklyLimit: raw.weekly_boss_clear_limit_count ?? 12,
    bosses,
    daily: (raw.daily_contents ?? []).map(parseContent),
    weekly: (raw.weekly_contents ?? []).map(parseContent),
  };
}

export interface RevenueLine {
  boss: string;
  diff: Difficulty;
  cycle: BossCycle;
  price: number | null;
  party: number;
  /** price ÷ party (floor). price null 이면 null */
  value: number | null;
}

export interface RevenueSummary {
  lines: RevenueLine[];
  byCycle: Record<BossCycle, { count: number; gross: number; value: number }>;
  totalGross: number;
  totalValue: number;
  unpriced: string[];
}

/**
 * 클리어된 보스의 결정 수익 추정. 등록 여부와 무관하게 completed 기준.
 * partyOf(boss, diff) 로 인원 지정. 없으면 1인(솔로).
 */
export function estimateRevenue(
  bosses: BossClearRow[],
  priceDate: string,
  partyOf: (boss: string, diff: string) => number = () => 1,
): RevenueSummary {
  const byCycle: RevenueSummary["byCycle"] = {
    bossDaily: { count: 0, gross: 0, value: 0 },
    bossWeekly: { count: 0, gross: 0, value: 0 },
    bossMonthly: { count: 0, gross: 0, value: 0 },
  };
  const lines: RevenueLine[] = [];
  const unpriced: string[] = [];
  for (const b of bosses) {
    if (!b.completed) continue;
    const price = crystalPrice(b.boss, b.diff, priceDate);
    const party = Math.max(1, partyOf(b.boss, b.diff) || 1);
    const value = price == null ? null : Math.floor(price / party);
    lines.push({ boss: b.boss, diff: b.diff, cycle: b.cycle, price, party, value });
    const c = byCycle[b.cycle] ?? (byCycle[b.cycle] = { count: 0, gross: 0, value: 0 });
    c.count++;
    if (price == null) unpriced.push(`${b.boss} ${b.diff}`);
    else {
      c.gross += price;
      c.value += value!;
    }
  }
  const totalGross = Object.values(byCycle).reduce((s, c) => s + c.gross, 0);
  const totalValue = Object.values(byCycle).reduce((s, c) => s + c.value, 0);
  return { lines, byCycle, totalGross, totalValue, unpriced };
}

/** 실측 클리어 중 티어 최고 행 (상한 산정용). 티어 미배정 보스는 제외. */
export function highestClearedTier(bosses: BossClearRow[]): BossClearRow | null {
  let best: BossClearRow | null = null;
  for (const b of bosses) {
    if (!b.completed || b.cycle !== "bossWeekly" || !b.tier) continue;
    if (!best || b.tier.rank > best.tier!.rank) best = b;
  }
  return best;
}

