  get isInvalidParam() {
    return this.code === "OPENAPI00004";
  }
  /** 점검/준비중 */
  get isMaintenance() {
    return ["OPENAPI00009", "OPENAPI00010", "OPENAPI00011"].includes(this.code);
  }
}

