import { useActionState } from "react";
import { registerNexonKey } from "@/actions/nexon-key";

export function KeyForm() {
  const [state, action, pending] = useActionState(registerNexonKey, null);
  return (
    <form action={action} className="space-y-2">
      <input name="apiKey" type="password" autoComplete="off" placeholder="test_ 또는 live_ 로 시작하는 키" className="input font-mono" required />
      <div className="flex items-center gap-3">
        <button className="btn-primary" disabled={pending}>
          {pending ? "검증 중…" : "저장"}
        </button>
        {state && <span className={`text-sm ${state.ok ? "text-green-700" : "text-red-600"}`}>{state.message}</span>}
      </div>
    </form>
  );
}

import Link from "next/link";
import { requireUserId } from "@/auth";
import { nexonKeyStatus } from "@/lib/db/queries/nexonKeys";
import { listOwnedCharacters } from "@/services/characterSync";
import { latestSnapshot, parsed } from "@/services/snapshotService";
import { estimateRevenue } from "@/lib/maple/scheduler";
import { kstDateStr } from "@/lib/maple/kst";
import { CharacterCard } from "@/components/character/CharacterCard";
import { ResyncButton } from "@/components/character/ResyncButton";
import { partySizeLookup } from "@/services/partyLink";

export const metadata = { title: "내 캐릭터" };

export default async function MePage() {
  const userId = await requireUserId();
  const key = nexonKeyStatus(userId);
  if (!key) {
    return (
      <div className="card space-y-3">
        <h1 className="text-xl font-bold">내 캐릭터</h1>
        <p className="text-sm text-zinc-600 dark:text-zinc-400">넥슨 API 키를 먼저 등록해야 합니다.</p>
        <Link href="/settings/nexon-key" className="btn-primary w-fit">
          키 등록하기
        </Link>
      </div>
    );
  }

  const chars = listOwnedCharacters(userId, true);
  const priceDate = kstDateStr();
  const partyOf = partySizeLookup(userId);

  const cards = chars.map((c) => {
    const snap = parsed(latestSnapshot(c.id));
    const rev = snap ? estimateRevenue(snap.bosses.filter((b) => b.cycle === "bossWeekly"), priceDate, (b, d) => partyOf(c.id, b, d)) : null;
    return { c, snap, rev };
  });

  const byWorld = new Map<string, typeof cards>();
  for (const x of cards) {
    const w = x.c.world ?? "?";
    if (!byWorld.has(w)) byWorld.set(w, []);
    byWorld.get(w)!.push(x);
  }
  for (const list of byWorld.values()) list.sort((a, b) => (b.c.level ?? 0) - (a.c.level ?? 0));

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-3">
        <h1 className="text-xl font-bold">내 캐릭터</h1>
        <span className="text-sm text-zinc-500">{chars.length}개</span>
        <div className="ml-auto">
          <ResyncButton />
        </div>
      </div>
      {[...byWorld.entries()].sort((a, b) => b[1].length - a[1].length).map(([world, list]) => (
        <section key={world} className="space-y-2">
          <h2 className="font-semibold text-zinc-700 dark:text-zinc-300">
            {world} <span className="text-xs text-zinc-500">{list.length}</span>
          </h2>
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {list.map(({ c, snap, rev }) => (
              <CharacterCard key={c.ocid} character={c} snapshot={snap} revenue={rev} />
            ))}
          </div>
        </section>
      ))}
    </div>
  );
}

import Link from "next/link";
import type { Character } from "@/lib/db/schema";
import type { ParsedSnapshot, RevenueSummary } from "@/lib/maple/scheduler";
import { fmtPower } from "@/lib/maple/format";
import { RefreshButton } from "./RefreshButton";
import { HideToggle } from "./HideToggle";

export function CharacterCard({ character: c, snapshot, revenue }: { character: Character; snapshot: ParsedSnapshot | null; revenue: RevenueSummary | null }) {
  const wearingBest = c.bestSetupHash != null && c.curSetupHashes?.equipped === c.bestSetupHash;
  return (
    <div className={`card flex gap-3 ${c.hidden ? "opacity-50" : ""}`}>
      {c.imageUrl ? (
        // eslint-disable-next-line @next/next/no-img-element
        <img src={c.imageUrl} alt="" className="w-16 h-16 object-contain shrink-0" />
      ) : (
        <div className="w-16 h-16 rounded bg-zinc-100 dark:bg-zinc-800 shrink-0" />
      )}
      <div className="flex-1 min-w-0 text-sm space-y-1">
        <div className="flex items-baseline gap-2">
          <Link href={`/me/characters/${c.ocid}`} className="font-semibold truncate hover:underline">
            {c.name}
          </Link>
          <span className="text-xs text-zinc-500 truncate">
            {c.cls} · Lv.{c.level}
          </span>
        </div>
        <div>
          <span className="text-zinc-500">대표 전투력 </span>
          <span className="font-medium">{fmtPower(c.bestPower)}</span>
          {c.curPower != null && c.curPower !== c.bestPower && (
            <span className="text-xs text-zinc-500 ml-1">
              (현재 {fmtPower(c.curPower)}
              {!wearingBest && " · 다른 세팅"})
            </span>
          )}
        </div>
        <div className="flex items-center gap-3 text-xs text-zinc-600 dark:text-zinc-400">
          <span>
            주간 보스 {snapshot ? `${snapshot.weeklyClearCount}/${snapshot.weeklyLimit}` : "-"}
          </span>
          {revenue && <span>결정 {fmtPower(revenue.totalValue)}</span>}
        </div>
        <div className="flex items-center gap-2 pt-1">
          <RefreshButton ocid={c.ocid} />
          <HideToggle ocid={c.ocid} hidden={c.hidden} />
        </div>
      </div>
    </div>
  );
}

