import "server-only";
import { and, eq, isNull, sql } from "drizzle-orm";
import { db } from "@/lib/db";
import { characters, parties, partyMembers } from "@/lib/db/schema";

/**
 * 유저의 캐릭터가 속한 파티들로 (characterId, boss, diff) → 인원 조회 함수를 만든다.
 * 파티 인원 = party_members 수. 같은 캐릭터가 같은 보스에 여러 파티면 첫 것.
 */
export function partySizeLookup(userId: string): (characterId: number, boss: string, diff: string) => number {
  const rows = db
    .select({
      characterId: partyMembers.characterId,
      boss: parties.boss,
      difficulty: parties.difficulty,
      size: sql<number>`(select count(*) from party_members pm2 where pm2.party_id = ${parties.id})`,
    })
    .from(partyMembers)
    .innerJoin(parties, eq(partyMembers.partyId, parties.id))
    .innerJoin(characters, eq(partyMembers.characterId, characters.id))
    .where(eq(characters.ownerUserId, userId))
    .all();
  const map = new Map<string, number>();
  for (const r of rows) {
    if (r.characterId == null) continue;
    const k = `${r.characterId}|${r.boss}|${r.difficulty}`;
    if (!map.has(k)) map.set(k, Math.max(1, Number(r.size) || 1));
  }
  return (characterId, boss, diff) => map.get(`${characterId}|${boss}|${diff}`) ?? 1;
}

/** 캐릭터별 파티 유래 고정 픽: characterId → { "보스 diff": 인원 } */
export function partyPicksByCharacter(userId: string): Map<number, Record<string, number>> {
  const rows = db
    .select({
      characterId: partyMembers.characterId,
      boss: parties.boss,
      difficulty: parties.difficulty,
      size: sql<number>`(select count(*) from party_members pm2 where pm2.party_id = ${parties.id})`,
    })
    .from(partyMembers)
    .innerJoin(parties, eq(partyMembers.partyId, parties.id))
    .innerJoin(characters, eq(partyMembers.characterId, characters.id))
    .where(eq(characters.ownerUserId, userId))
    .all();
  const out = new Map<number, Record<string, number>>();
  for (const r of rows) {
    if (r.characterId == null) continue;
    const rec = out.get(r.characterId) ?? {};
    const key = `${r.boss} ${r.difficulty}`;
    if (!(key in rec)) rec[key] = Math.max(1, Number(r.size) || 1);
    out.set(r.characterId, rec);
  }
  return out;
}

/** 닉네임으로 미연결 멤버 자동 연결 (characterSync 이후 호출용) */
export function linkMembersByName(characterId: number, name: string): number {
  return db.update(partyMembers).set({ characterId }).where(and(eq(partyMembers.nickname, name), isNull(partyMembers.characterId))).run().changes;
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { requireUserId } from "@/auth";
import { ownedCharacterByOcid } from "@/services/characterSync";
import { latestSnapshot, parsed, snapshotOn } from "@/services/snapshotService";
import { powerHistory } from "@/services/characterRefresh";
import { partySizeLookup } from "@/services/partyLink";
import { estimateRevenue } from "@/lib/maple/scheduler";
import { kstDateStr, lastWednesdayKst } from "@/lib/maple/kst";
import { fmtPower } from "@/lib/maple/format";
import { RefreshButton } from "@/components/character/RefreshButton";
import { BossClearTable } from "@/components/character/BossClearTable";
import { RevenueSummary } from "@/components/character/RevenueSummary";
import { ContentsList } from "@/components/character/ContentsList";

export default async function CharacterPage({ params, searchParams }: PageProps<"/me/characters/[ocid]">) {
  const userId = await requireUserId();
  const { ocid } = await params;
  const sp = await searchParams;
  const c = ownedCharacterByOcid(userId, ocid);
  if (!c) notFound();

  const view = sp.view === "lastweek" ? "lastweek" : "current";
  const snap = view === "lastweek" ? parsed(snapshotOn(c.id, lastWednesdayKst())) : parsed(latestSnapshot(c.id));
  const priceDate = view === "lastweek" ? lastWednesdayKst() : kstDateStr();
  const partyOf = partySizeLookup(userId);
  const revenue = snap ? estimateRevenue(snap.bosses, priceDate, (b, d) => partyOf(c.id, b, d)) : null;
  const history = powerHistory(c.id, 30);
  const wearingBest = c.bestSetupHash != null && c.curSetupHashes?.equipped === c.bestSetupHash;

  return (
    <div className="space-y-6">
      <div className="flex items-start gap-4">
        {c.imageUrl && (
          // eslint-disable-next-line @next/next/no-img-element
          <img src={c.imageUrl} alt="" className="w-24 h-24 object-contain" />
        )}
        <div className="space-y-1">
          <h1 className="text-2xl font-bold">
            {c.name} <span className="text-base font-normal text-zinc-500">{c.world} · {c.cls} · Lv.{c.level}</span>
          </h1>
          <div className="text-sm">
            대표 전투력 <b>{fmtPower(c.bestPower)}</b>
            {c.bestPowerAt && <span className="text-zinc-500"> ({c.bestPowerAt.slice(0, 10)} 기준)</span>}
            <span className="ml-3">현재 {fmtPower(c.curPower)}</span>
            {!wearingBest && c.curPower != null && <span className="ml-1 badge bg-amber-100 text-amber-800">대표값과 다른 세팅 착용 중</span>}
          </div>
          <div className="flex items-center gap-2">
            <RefreshButton ocid={c.ocid} label="전투력·스케줄러 새로고침" />
            <a className="text-xs underline text-zinc-500" href={`https://maplescouter.com/ko/result?name=${encodeURIComponent(c.name)}`} target="_blank" rel="noreferrer">
              maplescouter
            </a>
          </div>
        </div>
      </div>

      <div className="flex items-center gap-2 text-sm">
        <Link href={`/me/characters/${ocid}`} className={`btn-ghost ${view === "current" ? "bg-zinc-100 dark:bg-zinc-800" : ""}`}>
          이번 주
        </Link>
        <Link href={`/me/characters/${ocid}?view=lastweek`} className={`btn-ghost ${view === "lastweek" ? "bg-zinc-100 dark:bg-zinc-800" : ""}`}>
          지난주 ({lastWednesdayKst()})
        </Link>
        {snap?.date && <span className="text-zinc-500">스냅샷 기준일 {snap.date.slice(0, 10)}</span>}
      </div>

      {!snap ? (
        <div className="card text-sm text-zinc-600">스케줄러 데이터가 없습니다. 새로고침을 눌러 조회하세요. (지난주는 수요일 밤 자동 스냅샷이 있어야 표시됩니다)</div>
      ) : (
        <div className="grid gap-4 lg:grid-cols-[1fr_20rem]">
          <div className="space-y-4">
            <BossClearTable bosses={snap.bosses} priceDate={priceDate} partyOf={(b, d) => partyOf(c.id, b, d)} weekly={`${snap.weeklyClearCount}/${snap.weeklyLimit}`} />
            <ContentsList title="일간 콘텐츠" items={snap.daily} />
            <ContentsList title="주간 콘텐츠" items={snap.weekly} />
          </div>
          <div className="space-y-4">
            {revenue && <RevenueSummary revenue={revenue} priceDate={priceDate} />}
            <div className="card text-sm">
              <h3 className="font-semibold mb-2">전투력 이력</h3>
              {history.length ? (
                <ul className="space-y-0.5 text-xs">
                  {history
                    .slice()
                    .reverse()
                    .slice(0, 10)
                    .map((h) => (
                      <li key={h.id} className="flex justify-between">
                        <span className="text-zinc-500">{h.measuredAt.slice(0, 16).replace("T", " ")}</span>
                        <span>{fmtPower(h.power)}</span>
                      </li>
                    ))}
                </ul>
              ) : (
                <div className="text-zinc-500 text-xs">기록 없음</div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

import type { BossClearRow } from "@/lib/maple/scheduler";
import { crystalPrice } from "@/lib/maple/prices";
import { tierLabel } from "@/lib/maple/tiers";
import { fmtPower } from "@/lib/maple/format";

const CYCLE_LABEL: Record<string, string> = { bossWeekly: "주간", bossDaily: "일간", bossMonthly: "월간" };

export function BossClearTable({ bosses, priceDate, partyOf, weekly }: { bosses: BossClearRow[]; priceDate: string; partyOf: (boss: string, diff: string) => number; weekly: string }) {
  const groups: Record<string, BossClearRow[]> = {};
  for (const b of bosses) (groups[b.cycle] ??= []).push(b);
  const order = ["bossWeekly", "bossDaily", "bossMonthly"];
  return (
    <div className="card space-y-4">
      <div className="flex items-baseline gap-2">
        <h2 className="font-semibold">보스</h2>
        <span className="text-sm text-zinc-500">주간 {weekly} 클리어</span>
      </div>
      {order.filter((k) => groups[k]?.length).map((cycle) => (
        <div key={cycle}>
          <h3 className="text-xs font-medium text-zinc-500 mb-1">{CYCLE_LABEL[cycle] ?? cycle}</h3>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <tbody>
                {groups[cycle].map((b) => {
                  const price = crystalPrice(b.boss, b.diff, priceDate);
                  const party = partyOf(b.boss, b.diff);
                  const value = price == null ? null : Math.floor(price / party);
                  return (
                    <tr key={`${b.boss}|${b.diff}`} className={`border-t border-zinc-100 dark:border-zinc-800 ${b.completed ? "" : "text-zinc-400"} ${!b.registered && !b.completed ? "hidden sm:table-row" : ""}`}>
                      <td className="py-1 w-6">{b.completed ? "✅" : "⬜"}</td>
                      <td className="py-1">
                        {b.boss} <span className="text-xs">{b.diff}</span>
                        {!b.registered && <span className="ml-1 text-[10px] text-zinc-400">미등록</span>}
                      </td>
                      <td className="py-1 text-xs text-zinc-500 whitespace-nowrap">{tierLabel(b.tier)}</td>
                      <td className="py-1 text-right whitespace-nowrap">
                        {price == null ? <span className="text-xs text-zinc-400">가격 미등록</span> : (
                          <>
                            {fmtPower(price)}
                            {party > 1 && <span className="text-xs text-zinc-500"> ÷{party} = {fmtPower(value)}</span>}
                          </>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      ))}
      <p className="text-[11px] text-zinc-400">미등록·미클리어 행은 좁은 화면에서 숨김. 클리어 판정은 등록 여부와 무관하게 실제 클리어(complete_flag) 기준.</p>
    </div>
  );
}

import type { RevenueSummary as Rev } from "@/lib/maple/scheduler";
import { fmtPower } from "@/lib/maple/format";

export function RevenueSummary({ revenue, priceDate }: { revenue: Rev; priceDate: string }) {
  const rows = [
    ["주간", revenue.byCycle.bossWeekly],
    ["일간", revenue.byCycle.bossDaily],
    ["월간", revenue.byCycle.bossMonthly],
  ] as const;
  return (
    <div className="card text-sm space-y-2">
      <h3 className="font-semibold">결정 수익 추정</h3>
      <div className="text-xs text-zinc-500">{priceDate} 가격 · 파티 등록 인원 반영 · 전량 판매 가정</div>
      <table className="w-full">
        <tbody>
          {rows.filter(([, c]) => c.count).map(([label, c]) => (
            <tr key={label} className="border-t border-zinc-100 dark:border-zinc-800">
              <td className="py-1">{label}</td>
              <td className="py-1 text-zinc-500">{c.count}개</td>
              <td className="py-1 text-right">{fmtPower(c.value)}</td>
            </tr>
          ))}
          <tr className="border-t border-zinc-300 dark:border-zinc-700 font-semibold">
            <td className="py-1">합계</td>
            <td />
            <td className="py-1 text-right">{fmtPower(revenue.totalValue)}</td>
          </tr>
        </tbody>
      </table>
      {revenue.totalGross !== revenue.totalValue && <div className="text-xs text-zinc-500">결정 정가 합 {fmtPower(revenue.totalGross)} (파티 분배 전)</div>}
      {revenue.unpriced.length > 0 && <div className="text-xs text-amber-700">가격 미등록: {revenue.unpriced.join(", ")}</div>}
    </div>
  );
}

import type { ContentRow } from "@/lib/maple/scheduler";

const QUEST_LABEL: Record<string, string> = { todo: "⬜ 미완료", progress: "🔄 진행중", done: "✅ 완료", unknown: "?" };

export function ContentsList({ title, items }: { title: string; items: ContentRow[] }) {
  if (!items.length) return null;
  return (
    <div className="card text-sm">
      <h3 className="font-semibold mb-2">{title}</h3>
      <ul className="space-y-0.5">
        {items.map((c) => (
          <li key={c.name} className={`flex justify-between gap-2 ${c.registered ? "" : "text-zinc-400"}`}>
            <span className="truncate">
              {c.kind === "quest" && <span className="text-xs mr-1">[퀘스트]</span>}
              {c.name}
            </span>
            <span className="whitespace-nowrap text-xs">{c.kind === "quest" ? QUEST_LABEL[c.questState ?? "unknown"] : c.max > 0 ? `${c.now}/${c.max}` : `${c.now}`}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

