@import "tailwindcss";

@theme inline {
  --font-sans: ui-sans-serif, system-ui, "Apple SD Gothic Neo", "Malgun Gothic", "Noto Sans KR", sans-serif;
}

body {
  font-family: var(--font-sans);
}

/* Tailwind v4: @apply 안에서 커스텀 클래스를 다시 @apply 할 수 없어 유틸리티를 그대로 나열 */
@layer components {
  .card {
    @apply rounded-xl border border-zinc-200 bg-white p-4 shadow-sm dark:border-zinc-800 dark:bg-zinc-900;
  }
  .btn-primary {
    @apply inline-flex items-center gap-1 rounded-md px-3 py-1.5 text-sm font-medium transition disabled:opacity-50 disabled:cursor-not-allowed bg-orange-500 text-white hover:bg-orange-600;
  }
  .btn-ghost {
    @apply inline-flex items-center gap-1 rounded-md px-3 py-1.5 text-sm font-medium transition disabled:opacity-50 disabled:cursor-not-allowed border border-zinc-300 hover:bg-zinc-100 dark:border-zinc-700 dark:hover:bg-zinc-800;
  }
  .input {
    @apply w-full rounded-md border border-zinc-300 bg-white px-3 py-2 text-sm dark:border-zinc-700 dark:bg-zinc-900;
  }
  .badge {
    @apply inline-block rounded px-1.5 py-0.5 text-xs font-medium;
  }
}

