import NextAuth, { type NextAuthRequest } from "next-auth";
import type { NextFetchEvent, NextRequest } from "next/server";
import { authConfig } from "./auth.config";

// 로그인 가드. authConfig.callbacks.authorized 가 false 면 pages.signIn(/login)으로 리다이렉트.
// Edge 런타임: DB 어댑터 없는 authConfig 만 사용 (세션은 JWT).
const { auth } = NextAuth(authConfig);

export default function proxy(req: NextRequest, event: NextFetchEvent) {
  return auth(req as NextAuthRequest, event);
}

export const config = {
  matcher: ["/me/:path*", "/settings/:path*", "/parties/:path*", "/planner/:path*"],
};

