import "server-only";
import { and, eq } from "drizzle-orm";
import { db } from "@/lib/db";
import { planConfigs } from "@/lib/db/schema";
import { listOwnedCharacters } from "./characterSync";
import { ceilingSnapshots, latestSnapshot, parsed } from "./snapshotService";
import { partyPicksByCharacter } from "./partyLink";
import type { BossClearRow } from "@/lib/maple/scheduler";
import type { PlanConfig } from "@/lib/maple/planner";

/** 클라이언트 PlannerBoard 에 넘기는 캐릭터 단위 입력. 상한 산정용 클리어 행은 주간·완료만 추린다. */
export interface PlannerCharacter {
  ocid: string;
  name: string;
  cls: string | null;
  level: number | null;
  world: string | null;
  hidden: boolean;
  cap: number;
  clearedWeekly: BossClearRow[][];
  /** 실시간 스냅샷의 등록(registration_flag) 주간 보스 — 'init' 용 */
  registeredWeekly: BossClearRow[];
  partyPicks: Record<string, number>;
  snapshotDates: string[];
}

export interface PlannerWorldInput {
  world: string;
  characters: PlannerCharacter[];
  config: PlanConfig;
}

const DEFAULT_LIMIT = Number(process.env.WEEKLY_WORLD_SALE_LIMIT ?? 90);

export function loadPlanConfig(userId: string, world: string): PlanConfig {
  const row = db.select().from(planConfigs).where(and(eq(planConfigs.userId, userId), eq(planConfigs.world, world))).get();
  const cfg = (row?.config as PlanConfig | undefined) ?? { characters: {} };
  return { default_party: cfg.default_party ?? 1, world_limit: cfg.world_limit ?? DEFAULT_LIMIT, characters: cfg.characters ?? {} };
}

export function savePlanConfigRow(userId: string, world: string, config: PlanConfig) {
  db.insert(planConfigs)
    .values({ userId, world, config, updatedAt: new Date().toISOString() })
    .onConflictDoUpdate({ target: [planConfigs.userId, planConfigs.world], set: { config, updatedAt: new Date().toISOString() } })
    .run();
}

export function buildPlannerInputs(userId: string): PlannerWorldInput[] {
  const chars = listOwnedCharacters(userId, true);
  const partyPicks = partyPicksByCharacter(userId);
  const byWorld = new Map<string, PlannerCharacter[]>();
  for (const c of chars) {
    const snaps = ceilingSnapshots(c.id);
    const latest = parsed(latestSnapshot(c.id));
    const item: PlannerCharacter = {
      ocid: c.ocid,
      name: c.name,
      cls: c.cls,
      level: c.level,
      world: c.world,
      hidden: c.hidden,
      cap: snaps[0]?.weeklyLimit ?? 12,
      clearedWeekly: snaps.map((s) => s.bosses.filter((b) => b.cycle === "bossWeekly" && b.completed)),
      registeredWeekly: latest?.bosses.filter((b) => b.cycle === "bossWeekly" && b.registered) ?? [],
      partyPicks: partyPicks.get(c.id) ?? {},
      snapshotDates: snaps.map((s) => s.date?.slice(0, 10) ?? "?"),
    };
    const w = c.world ?? "?";
    if (!byWorld.has(w)) byWorld.set(w, []);
    byWorld.get(w)!.push(item);
  }
  return [...byWorld.entries()]
    .sort((a, b) => b[1].length - a[1].length)
    .map(([world, characters]) => ({ world, characters: characters.sort((a, b) => (b.level ?? 0) - (a.level ?? 0)), config: loadPlanConfig(userId, world) }));
}

"use server";

import { revalidatePath } from "next/cache";
import { z } from "zod";
import { requireUserId } from "@/auth";
import { savePlanConfigRow } from "@/services/planInput";
import type { PlanConfig } from "@/lib/maple/planner";
import type { ActionResult } from "./nexon-key";

const CharSchema = z.object({
  skip: z.boolean().optional(),
  auto: z.boolean().optional(),
  party: z.number().int().min(1).max(6).optional(),
  ceiling: z.string().max(40).optional(),
  bosses: z.record(z.string().max(40), z.number().int().min(1).max(6)).optional(),
  _note: z.string().max(200).optional(),
});
const ConfigSchema = z.object({
  default_party: z.number().int().min(1).max(6).optional(),
  world_limit: z.number().int().min(1).max(500).optional(),
  characters: z.record(z.string().max(64), CharSchema),
});

export async function savePlanConfig(world: string, config: PlanConfig): Promise<ActionResult> {
  const userId = await requireUserId();
  const p = ConfigSchema.safeParse(config);
  if (!p.success) return { ok: false, message: p.error.issues[0]?.message ?? "설정 형식 오류" };
  if (!world || world.length > 20) return { ok: false, message: "월드 오류" };
  savePlanConfigRow(userId, world, p.data as PlanConfig);
  revalidatePath("/planner");
  return { ok: true, message: "저장됨" };
}

import Link from "next/link";
import { requireUserId } from "@/auth";
import { nexonKeyStatus } from "@/lib/db/queries/nexonKeys";
import { buildPlannerInputs } from "@/services/planInput";
import { kstDateStr } from "@/lib/maple/kst";
import { priceChangeDates } from "@/lib/maple/prices";
import { PlannerBoard } from "@/components/planner/PlannerBoard";

export const metadata = { title: "주간 결정 플래너" };

export default async function PlannerPage() {
  const userId = await requireUserId();
  if (!nexonKeyStatus(userId)) {
    return (
      <div className="card space-y-2">
        <h1 className="text-xl font-bold">주간 결정 플래너</h1>
        <p className="text-sm text-zinc-600">넥슨 API 키를 등록하고 캐릭터를 연동해야 사용할 수 있습니다.</p>
        <Link href="/settings/nexon-key" className="btn-primary w-fit">
          키 등록
        </Link>
      </div>
    );
  }
  const worlds = buildPlannerInputs(userId);
  return (
    <div className="space-y-4">
      <div>
        <h1 className="text-xl font-bold">주간 결정 플래너</h1>
        <p className="text-sm text-zinc-500">
          캐릭터당 주간 보스 한도와 월드 결정 한도 안에서 실수령(가격 ÷ 인원)이 최대가 되게 배분합니다. 상한은 최근 클리어 이력의 티어로 추정하며, 파티 등록 인원은 자동 반영됩니다.
        </p>
      </div>
      {worlds.length === 0 ? (
        <div className="card text-sm text-zinc-500">
          연동된 캐릭터가 없습니다. <Link href="/me" className="underline">내 캐릭터</Link>에서 동기화하세요.
        </div>
      ) : (
        <PlannerBoard worlds={worlds} today={kstDateStr()} changeDates={priceChangeDates()} />
      )}
    </div>
  );
}

"use client";

import { useMemo, useState, useTransition } from "react";
import type { PlannerWorldInput, PlannerCharacter } from "@/services/planInput";
import { allocatePlan, buildProfile, initCharConfigFromRegistration, type CharPlanConfig, type PlanConfig, type PlanProfile } from "@/lib/maple/planner";
import { weeklyCandidates } from "@/lib/maple/prices";
import { tierKeysByRank, tierLabel, tierOf } from "@/lib/maple/tiers";
import { fmtPower } from "@/lib/maple/format";
import { savePlanConfig } from "@/actions/planner";
import { CharacterPlanRow } from "./CharacterPlanRow";

export function PlannerBoard({ worlds, today, changeDates }: { worlds: PlannerWorldInput[]; today: string; changeDates: string[] }) {
  const [worldIdx, setWorldIdx] = useState(0);
  const [configs, setConfigs] = useState<Record<string, PlanConfig>>(() => Object.fromEntries(worlds.map((w) => [w.world, w.config])));
  const [priceDate, setPriceDate] = useState(today);
  const [msg, setMsg] = useState<string | null>(null);
  const [pending, start] = useTransition();

  const w = worlds[worldIdx];
  const cfg = configs[w.world];
  const limit = cfg.world_limit ?? 90;
  const defaultParty = cfg.default_party ?? 1;

  const dateOptions = useMemo(() => {
    const opts = [{ label: `오늘 (${today})`, value: today }];
    for (const d of changeDates) if (d > today) opts.push({ label: `${d} 이후`, value: d });
    return opts;
  }, [changeDates, today]);

  const { profiles, warnings, byId } = useMemo(() => {
    const profiles: PlanProfile[] = [];
    const warnings: string[] = [];
    const byId: Record<string, PlannerCharacter> = {};
    for (const c of w.characters) {
      byId[c.ocid] = c;
      const cc = cfg.characters[c.ocid];
      if (cc?.skip || (c.hidden && !cc)) continue;
      const r = buildProfile({ charId: c.ocid, name: c.name, cls: c.cls ?? undefined, level: c.level ?? undefined, world: c.world ?? undefined, cfg: cc, defaultParty, priceDate, snapshotBosses: c.clearedWeekly, cap: c.cap, partyPicks: c.partyPicks });
      profiles.push(r.profile);
      warnings.push(...r.warnings);
    }
    return { profiles, warnings, byId };
  }, [w, cfg, defaultParty, priceDate]);

  const plan = useMemo(() => allocatePlan({ priceDate, worldLimit: limit, candidates: weeklyCandidates(priceDate), profiles }), [priceDate, limit, profiles]);
  const rowById = Object.fromEntries(plan.rows.map((r) => [r.charId, r]));
  const tierOptions = useMemo(() => tierKeysByRank(), []);

  function patchChar(ocid: string, patch: Partial<CharPlanConfig> | null) {
    setConfigs((all) => {
      const next = { ...all[w.world], characters: { ...all[w.world].characters } };
      if (patch === null) delete next.characters[ocid];
      else next.characters[ocid] = { ...next.characters[ocid], ...patch };
      return { ...all, [w.world]: next };
    });
  }
  function patchWorld(patch: Partial<PlanConfig>) {
    setConfigs((all) => ({ ...all, [w.world]: { ...all[w.world], ...patch } }));
  }
  function initFromRegistration() {
    const next: Record<string, CharPlanConfig> = {};
    const lines: string[] = [];
    for (const c of w.characters) {
      const r = initCharConfigFromRegistration({ name: c.name, keep: cfg.characters[c.ocid], defaultParty, priceDate, bosses: c.registeredWeekly.length || c.clearedWeekly.length ? [...c.registeredWeekly, ...c.clearedWeekly.flat()] : null, cap: c.cap });
      next[c.ocid] = r.cfg;
      lines.push(r.summary);
    }
    patchWorld({ characters: next });
    setMsg(`스케줄러 등록 기준으로 초기화: ${lines.length}명`);
  }
  function save() {
    start(async () => {
      const r = await savePlanConfig(w.world, configs[w.world]);
      setMsg(r.message);
    });
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center gap-2 text-sm">
        {worlds.map((x, i) => (
          <button key={x.world} className={`btn-ghost ${i === worldIdx ? "bg-zinc-100 dark:bg-zinc-800" : ""}`} onClick={() => setWorldIdx(i)}>
            {x.world} <span className="text-xs text-zinc-500">{x.characters.length}</span>
          </button>
        ))}
        <div className="ml-auto flex flex-wrap items-center gap-2">
          <label className="flex items-center gap-1">
            <span className="text-xs text-zinc-500">가격</span>
            <select className="input w-auto py-1" value={priceDate} onChange={(e) => setPriceDate(e.target.value)}>
              {dateOptions.map((o) => (
                <option key={o.value} value={o.value}>
                  {o.label}
                </option>
              ))}
            </select>
          </label>
          <label className="flex items-center gap-1">
            <span className="text-xs text-zinc-500">월드 한도</span>
            <input type="number" className="input w-20 py-1" min={1} max={500} value={limit} onChange={(e) => patchWorld({ world_limit: Number(e.target.value) || 90 })} />
          </label>
          <label className="flex items-center gap-1">
            <span className="text-xs text-zinc-500">기본 인원</span>
            <input type="number" className="input w-16 py-1" min={1} max={6} value={defaultParty} onChange={(e) => patchWorld({ default_party: Math.min(6, Math.max(1, Number(e.target.value) || 1)) })} />
          </label>
          <button className="btn-ghost" onClick={initFromRegistration}>
            스케줄러 등록으로 초기화
          </button>
          <button className="btn-primary" disabled={pending} onClick={save}>
            {pending ? "저장 중…" : "설정 저장"}
          </button>
        </div>
      </div>
      {msg && <div className="text-sm text-zinc-600">{msg}</div>}

      <div className="card text-sm flex flex-wrap gap-x-6 gap-y-1">
        <span>
          결정 <b>{plan.count}</b>/{limit}개
        </span>
        <span>
          실수령 <b>{fmtPower(plan.worldValue)}</b>
        </span>
        <span className="text-zinc-500">정가 합 {fmtPower(plan.worldGross)}</span>
        {plan.count < limit && <span className="text-amber-700">한도 미달 {limit - plan.count}개 — 캐릭터 추가 또는 상한 상향</span>}
        {plan.idle.length > 0 && <span className="text-zinc-500">배분 0개: {plan.idle.map((id) => byId[id]?.name ?? id).join(", ")}</span>}
      </div>
      {(warnings.length > 0 || plan.warnings.length > 0) && (
        <ul className="text-xs text-amber-700 list-disc pl-5">
          {[...warnings, ...plan.warnings].map((x, i) => (
            <li key={i}>{x}</li>
          ))}
        </ul>
      )}

      <div className="space-y-3">
        {w.characters.map((c) => (
          <CharacterPlanRow
            key={c.ocid}
            character={c}
            cfg={cfg.characters[c.ocid]}
            profile={profiles.find((p) => p.charId === c.ocid) ?? null}
            row={rowById[c.ocid] ?? null}
            priceDate={priceDate}
            defaultParty={defaultParty}
            tierOptions={tierOptions}
            onPatch={(p) => patchChar(c.ocid, p)}
          />
        ))}
      </div>
      <p className="text-[11px] text-zinc-400">
        티어 기준: {tierLabel(tierOf("찬란한 흉성", "normal"))} 같은 표기는 나무위키 보스 티어. 상한 티어 이하 보스만 자동 배분됩니다. 고정 픽(📌)은 상한과 무관하게 항상 포함.
      </p>
    </div>
  );
}

"use client";

import { useState } from "react";
import type { PlannerCharacter } from "@/services/planInput";
import type { CharPlanConfig, PlanProfile, PlanRow } from "@/lib/maple/planner";
import { normalizeBossList, parseBossKey } from "@/lib/maple/bossKey";
import { crystalPrice, PRICE_TABLE } from "@/lib/maple/prices";
import { tierLabel, tierOf, type Tier } from "@/lib/maple/tiers";
import { fmtPower } from "@/lib/maple/format";

export function CharacterPlanRow({
  character: c,
  cfg,
  profile,
  row,
  priceDate,
  defaultParty,
  tierOptions,
  onPatch,
}: {
  character: PlannerCharacter;
  cfg: CharPlanConfig | undefined;
  profile: PlanProfile | null;
  row: PlanRow | null;
  priceDate: string;
  defaultParty: number;
  tierOptions: { key: string; tier: Tier }[];
  onPatch: (patch: Partial<CharPlanConfig> | null) => void;
}) {
  const [open, setOpen] = useState(false);
  const skip = cfg?.skip ?? false;
  const party = cfg?.party ?? defaultParty;
  const auto = cfg?.auto ?? !(cfg?.bosses && Object.keys(cfg.bosses).length);
  const bosses = Object.fromEntries(normalizeBossList(cfg?.bosses).map((b) => [b.key, b.party ?? party]));

  function setBosses(next: Record<string, number>) {
    onPatch({ bosses: next, auto: cfg?.auto ?? Object.keys(next).length === 0 });
  }

  const bossKeys = Object.entries(PRICE_TABLE.prices)
    .flatMap(([b, diffs]) => Object.keys(diffs).map((d) => `${b} ${d}`))
    .filter((k) => {
      const r = parseBossKey(k)!;
      return tierOf(r.boss, r.diff) && crystalPrice(r.boss, r.diff, priceDate) != null && !(k in bosses);
    })
    .sort((a, b) => (tierOf(parseBossKey(b)!.boss, parseBossKey(b)!.diff)?.rank ?? 0) - (tierOf(parseBossKey(a)!.boss, parseBossKey(a)!.diff)?.rank ?? 0));

  return (
    <div className={`card text-sm ${skip ? "opacity-60" : ""}`}>
      <div className="flex flex-wrap items-center gap-3">
        <button className="font-semibold hover:underline" onClick={() => setOpen((o) => !o)}>
          {open ? "▾" : "▸"} {c.name}
        </button>
        <span className="text-xs text-zinc-500">
          {c.cls} Lv.{c.level}
        </span>
        {profile?.ceiling ? (
          <span className="text-xs">
            상한 {profile.ceiling.boss} {profile.ceiling.diff} <span className="text-zinc-500">({tierLabel(profile.ceiling.tier)} · {profile.ceilingSource === "manual" ? "수동" : `실측 ${profile.clearedCount}클`})</span>
          </span>
        ) : (
          !skip && <span className="text-xs text-amber-700">상한 미파악 — 아래에서 지정</span>
        )}
        <span className="ml-auto text-xs text-zinc-500">{c.snapshotDates.length ? `스냅샷 ${c.snapshotDates.join(", ")}` : "스냅샷 없음"}</span>
        {row && (
          <span className="font-medium">
            {row.picks.length}개 {fmtPower(row.value)}
          </span>
        )}
      </div>

      {row && !open && (
        <div className="mt-2 flex flex-wrap gap-1">
          {row.picks.map((p) => (
            <span key={`${p.boss}|${p.diff}`} className={`badge ${p.fixed ? "bg-orange-50 text-orange-800 dark:bg-orange-900/30 dark:text-orange-200" : "bg-zinc-100 text-zinc-700 dark:bg-zinc-800 dark:text-zinc-300"}`} title={`${fmtPower(p.price)}${p.party > 1 ? ` ÷${p.party}` : ""} · ${tierLabel(p.tier)}${p.source === "party" ? " · 파티" : ""}`}>
              {p.fixed && "📌"}
              {p.boss} {p.diff}
              {p.party > 1 && <span className="opacity-60"> {p.party}인</span>}
            </span>
          ))}
        </div>
      )}

      {open && (
        <div className="mt-3 grid gap-4 md:grid-cols-2">
          <div className="space-y-3">
            <div className="flex flex-wrap items-center gap-3">
              <label className="flex items-center gap-1">
                <input type="checkbox" checked={skip} onChange={(e) => onPatch({ skip: e.target.checked })} /> 제외
              </label>
              <label className="flex items-center gap-1">
                <input type="checkbox" checked={auto} onChange={(e) => onPatch({ auto: e.target.checked })} /> 남는 슬롯 자동 채움
              </label>
              <label className="flex items-center gap-1">
                기본 인원
                <input type="number" className="input w-16 py-0.5" min={1} max={6} value={party} onChange={(e) => onPatch({ party: Math.min(6, Math.max(1, Number(e.target.value) || 1)) })} />
              </label>
            </div>
            <label className="block">
              <div className="text-xs text-zinc-500 mb-1">상한 수동 지정 (비우면 실측)</div>
              <select className="input" value={cfg?.ceiling ?? ""} onChange={(e) => onPatch({ ceiling: e.target.value || undefined })}>
                <option value="">실측 클리어 기준</option>
                {tierOptions.map((o) => (
                  <option key={o.key} value={o.key}>
                    {o.key} ({tierLabel(o.tier)})
                  </option>
                ))}
              </select>
            </label>
            <div>
              <div className="text-xs text-zinc-500 mb-1">고정 픽 (보스 · 인원) — 파티 등록 항목은 자동 포함</div>
              <ul className="space-y-1">
                {Object.entries(bosses).map(([k, n]) => (
                  <li key={k} className="flex items-center gap-2">
                    <span className="flex-1">
                      📌 {k} <span className="text-xs text-zinc-500">{tierLabel(tierOf(parseBossKey(k)!.boss, parseBossKey(k)!.diff))}</span>
                    </span>
                    <input type="number" className="input w-16 py-0.5" min={1} max={6} value={n} onChange={(e) => setBosses({ ...bosses, [k]: Math.min(6, Math.max(1, Number(e.target.value) || 1)) })} />
                    <button className="btn-ghost py-0.5" onClick={() => { const next = { ...bosses }; delete next[k]; setBosses(next); }}>
                      ×
                    </button>
                  </li>
                ))}
                {Object.entries(c.partyPicks).filter(([k]) => !(k in bosses)).map(([k, n]) => (
                  <li key={k} className="flex items-center gap-2 text-zinc-500">
                    <span className="flex-1">🔒 {k}</span>
                    <span className="text-xs">{n}인 (파티)</span>
                  </li>
                ))}
              </ul>
              <select className="input mt-1" value="" onChange={(e) => e.target.value && setBosses({ ...bosses, [e.target.value]: party })}>
                <option value="">+ 보스 추가</option>
                {bossKeys.map((k) => (
                  <option key={k} value={k}>
                    {k} · {tierLabel(tierOf(parseBossKey(k)!.boss, parseBossKey(k)!.diff))} · {fmtPower(crystalPrice(parseBossKey(k)!.boss, parseBossKey(k)!.diff, priceDate))}
                  </option>
                ))}
              </select>
            </div>
            <button className="text-xs underline text-zinc-500" onClick={() => onPatch(null)}>
              이 캐릭터 설정 초기화
            </button>
          </div>
          <div>
            <div className="text-xs text-zinc-500 mb-1">배분 결과</div>
            {row ? (
              <table className="w-full">
                <tbody>
                  {row.picks.map((p) => (
                    <tr key={`${p.boss}|${p.diff}`} className="border-t border-zinc-100 dark:border-zinc-800">
                      <td className="py-0.5 w-5">{p.fixed ? "📌" : ""}</td>
                      <td className="py-0.5">
                        {p.boss} <span className="text-xs text-zinc-500">{p.diff}</span>
                      </td>
                      <td className="py-0.5 text-xs text-zinc-500">{tierLabel(p.tier)}</td>
                      <td className="py-0.5 text-right whitespace-nowrap">
                        {fmtPower(p.price)}
                        {p.party > 1 && <span className="text-xs text-zinc-500"> ÷{p.party} = {fmtPower(p.value)}</span>}
                      </td>
                    </tr>
                  ))}
                  <tr className="border-t border-zinc-300 dark:border-zinc-700 font-semibold">
                    <td colSpan={3} className="py-0.5">
                      합계 {row.picks.length}개
                    </td>
                    <td className="py-0.5 text-right">{fmtPower(row.value)}</td>
                  </tr>
                </tbody>
              </table>
            ) : (
              <div className="text-zinc-500 text-xs">배분 없음</div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

