                      </td>
                    </tr>
                  ))}
                  <tr className="border-t border-zinc-300 dark:border-zinc-700 font-semibold">
                    <td colSpan={3} className="py-0.5">
                      합계 {row.picks.length}개
                    </td>
                    <td className="py-0.5 text-right">{fmtPower(row.value)}</td>
