2	import { JOB_NAMES, runJob, type JobName } from "@/jobs/runner";
3	import { clientIpFrom, isLoopbackIp } from "@/lib/limiter";
4	
5	/**
6	 * 수동 잡 실행. Authorization: Bearer $JOBS_SECRET.
7	 * production 에서는 기본으로 루프백(127.0.0.1)에서 온 요청만 허용 (nginx 가 X-Real-IP 를 붙인다는 전제).
8	 * 외부에서 호출해야 하면 JOBS_LOOPBACK_ONLY=0. nginx 단에서도 /api/jobs/ 를 allow 127.0.0.1; deny all; 로 막아둔다.
9	 */
10	export async function POST(req: Request, ctx: RouteContext<"/api/jobs/[name]">) {
11	  const secret = process.env.JOBS_SECRET;
12	  const auth = req.headers.get("authorization") ?? "";
13	  if (!secret || auth !== `Bearer ${secret}`) return NextResponse.json({ error: "unauthorized" }, { status: 401 });
14	  const loopbackOnly = process.env.NODE_ENV === "production" && process.env.JOBS_LOOPBACK_ONLY !== "0";
15	  if (loopbackOnly && !isLoopbackIp(clientIpFrom(req.headers))) return NextResponse.json({ error: "forbidden" }, { status: 403 });
16	  const { name } = await ctx.params;
17	  if (!(JOB_NAMES as readonly string[]).includes(name)) return NextResponse.json({ error: "unknown job", jobs: JOB_NAMES }, { status: 404 });
18	  try {
19	    const r = await runJob(name as JobName);
20	    return NextResponse.json(r);
21	  } catch (e) {
22	    return NextResponse.json({ status: "failed", error: e instanceof Error ? e.message : String(e) }, { status: 500 });
23	  }

