// Discord OAuth 시작 요청이 discord.com 인가 URL로 리다이렉트되는지 확인 (자격증명 값은 출력하지 않음)
import { readFileSync } from "node:fs";
const env = Object.fromEntries(readFileSync("C:/Users/SSAFY/Documents/pjt/maple-board/.env.local", "utf8").split(/\r?\n/).filter((l) => l.includes("=")).map((l) => { const i = l.indexOf("="); return [l.slice(0, i).trim(), l.slice(i + 1).trim()]; }));
console.log("AUTH_DISCORD_ID set:", !!env.AUTH_DISCORD_ID, `(len ${env.AUTH_DISCORD_ID?.length ?? 0})`, "| SECRET set:", !!env.AUTH_DISCORD_SECRET, `(len ${env.AUTH_DISCORD_SECRET?.length ?? 0})`);

const base = "http://localhost:3000";
const jar = new Map();
const cookieHeader = () => [...jar.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
async function get(path, opts = {}) {
  const res = await fetch(base + path, { ...opts, headers: { cookie: cookieHeader(), ...(opts.headers ?? {}) }, redirect: "manual" });
  for (const c of res.headers.getSetCookie?.() ?? []) { const [pair] = c.split(";"); const i = pair.indexOf("="); jar.set(pair.slice(0, i).trim(), pair.slice(i + 1).trim()); }
  return res;
}
const { csrfToken } = await (await get("/api/auth/csrf")).json();
const res = await get("/api/auth/signin/discord", { method: "POST", headers: { "content-type": "application/x-www-form-urlencoded" }, body: new URLSearchParams({ csrfToken, callbackUrl: "/me" }) });
const loc = res.headers.get("location") ?? "";
const u = loc ? new URL(loc) : null;
console.log("signin ->", res.status, u ? `${u.origin}${u.pathname}` : "(no redirect)");
if (u) {
  console.log("  client_id matches env:", u.searchParams.get("client_id") === env.AUTH_DISCORD_ID);
  console.log("  scope:", u.searchParams.get("scope"));
  console.log("  redirect_uri:", u.searchParams.get("redirect_uri"));
}

