const base = "http://localhost:3000";
const jar = new Map();
const cookieHeader = () => [...jar.entries()].map(([k, v]) => `${k}=${v}`).join("; ");
async function get(path, opts = {}) {
  const res = await fetch(base + path, { ...opts, headers: { cookie: cookieHeader(), ...(opts.headers ?? {}) }, redirect: "manual" });
  for (const c of res.headers.getSetCookie?.() ?? []) { const [pair] = c.split(";"); const i = pair.indexOf("="); jar.set(pair.slice(0, i).trim(), pair.slice(i + 1).trim()); }
  return res;
}
const { csrfToken } = await (await get("/api/auth/csrf")).json();
await get("/api/auth/callback/dev", { method: "POST", headers: { "content-type": "application/x-www-form-urlencoded" }, body: new URLSearchParams({ csrfToken, username: "tester", redirect: "false" }) });
for (const p of ["/me", "/me?all=1"]) {
  const res = await get(p);
  const html = (await res.text()).replace(/<!--\s*-->/g, "");
  const text = html.replace(/<script[\s\S]*?<\/script>/g, "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ");
  const i = text.indexOf("내 캐릭터 ");
  console.log(p, res.status, "|", text.slice(i, i + 110));
  console.log("  cards:", (html.match(/w-28 h-28/g) ?? []).length, "| has 봉풀르르(257):", text.includes("봉풀르르"), "| has 알전임:", text.includes("알전임"));
}

