// 넥슨 캐릭터 이미지 실제 크기와 비투명 영역(바운딩 박스) 측정
const Database = require("C:/Users/SSAFY/Documents/pjt/maple-board/node_modules/better-sqlite3");
const zlib = require("node:zlib");
const db = new Database("C:/Users/SSAFY/Documents/pjt/maple-board/data/app.db", { readonly: true });
const rows = db.prepare("select name, image_url from characters where image_url is not null and level >= 260 order by level desc limit 3").all();

function decodePng(buf) {
  let off = 8; const chunks = []; let w, h, bitDepth, colorType;
  while (off < buf.length) {
    const len = buf.readUInt32BE(off); const type = buf.toString("ascii", off + 4, off + 8); const data = buf.subarray(off + 8, off + 8 + len);
    if (type === "IHDR") { w = data.readUInt32BE(0); h = data.readUInt32BE(4); bitDepth = data[8]; colorType = data[9]; }
    if (type === "IDAT") chunks.push(data);
    off += 12 + len;
  }
  const raw = zlib.inflateSync(Buffer.concat(chunks));
  const bpp = colorType === 6 ? 4 : colorType === 2 ? 3 : colorType === 4 ? 2 : 1;
  if (bitDepth !== 8 || (colorType !== 6 && colorType !== 2)) return { w, h, bitDepth, colorType, note: "unsupported for alpha scan" };
  const stride = w * bpp; const out = Buffer.alloc(w * h * bpp); let prev = Buffer.alloc(stride);
  for (let y = 0; y < h; y++) {
    const f = raw[y * (stride + 1)]; const line = Buffer.from(raw.subarray(y * (stride + 1) + 1, (y + 1) * (stride + 1)));
    for (let i = 0; i < stride; i++) {
      const a = i >= bpp ? line[i - bpp] : 0, b = prev[i], c = i >= bpp ? prev[i - bpp] : 0;
      let v = line[i];
      if (f === 1) v += a; else if (f === 2) v += b; else if (f === 3) v += (a + b) >> 1; else if (f === 4) { const p = a + b - c, pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c); v += pa <= pb && pa <= pc ? a : pb <= pc ? b : c; }
      line[i] = v & 255;
    }
    line.copy(out, y * stride); prev = line;
  }
  let minX = w, minY = h, maxX = -1, maxY = -1;
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const alpha = colorType === 6 ? out[(y * w + x) * 4 + 3] : 255;
    if (alpha > 10) { if (x < minX) minX = x; if (x > maxX) maxX = x; if (y < minY) minY = y; if (y > maxY) maxY = y; }
  }
  return { w, h, colorType, bbox: { minX, minY, maxX, maxY, bw: maxX - minX + 1, bh: maxY - minY + 1 } };
}

(async () => {
  for (const r of rows) {
    const res = await fetch(r.image_url);
    const buf = Buffer.from(await res.arrayBuffer());
    console.log(r.name, res.headers.get("content-type"), buf.length, "bytes");
    console.log("  ", decodePng(buf));
  }
})();

