2	/**
3	 * 메이플 파티 결성 보드 — 넥슨 Open API 조회 프로토타입 v2
4	 *
5	 * v2 변경점: 전투력 대표값 로직 개선
6	 *  - 최대 전투력 기록 시 당시 착용 장비 구성(해시)을 함께 저장
7	 *  - 갱신 시 현재 장비 프리셋 1/2/3 + 착용 구성과 대조:
8	 *      · 저장된 구성이 존재 → 세팅 유지 중 → 최대치 유지 (드메템 착용과 무관)
9	 *      · 어디에도 없음     → 세팅 변경됨 → 최대치 무효화, 현재 값으로 재설정
10	 *
11	 * 사용법
12	 *  export NEXON_API_KEY=발급받은키
13	 *  node maple-proto.js char 알전임    # 조회 + 전투력/세팅 기록
14	 *  node maple-proto.js log 알전임     # 기록 확인
15	 *  node maple-proto.js my-list       # 내 계정 캐릭터 목록 (키 소유 계정 한정)
16	 */
17	
18	const fs = require("fs");
19	const path = require("path");
20	const crypto = require("crypto");
21	
22	const BASE = "https://open.api.nexon.com";
23	const API_KEY = process.env.NEXON_API_KEY;
24	const LOG_FILE = path.join(__dirname, "power_log.json");
25	
26	// ---------- API 호출 공통 ----------
27	
28	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
29	
30	async function nx(endpoint, params = {}, retry = 2) {
31	  const qs = new URLSearchParams(params).toString();
32	  const url = `${BASE}${endpoint}${qs ? "?" + qs : ""}`;
33	  const res = await fetch(url, { headers: { "x-nxopen-api-key": API_KEY } });
34	  const body = await res.json();
35	  if (!res.ok) {
36	    const msg = body?.error?.message || res.statusText;
37	    const name = body?.error?.name || res.status;
38	    // OPENAPI00007 = 호출 한도(5건/초). 잠깐 쉬고 재시도.
39	    if (name === "OPENAPI00007" && retry > 0) { await sleep(1200); return nx(endpoint, params, retry - 1); }
40	    throw new Error(`[${name}] ${msg} (${endpoint})`);
41	  }
42	  return body;
43	}
44	
45	const getOcid = async (name) =>
46	  (await nx("/maplestory/v1/id", { character_name: name })).ocid;
47	const getBasic = (ocid) => nx("/maplestory/v1/character/basic", { ocid });
48	const getEquipment = (ocid) => nx("/maplestory/v1/character/item-equipment", { ocid });
49	const getMyCharacterList = () => nx("/maplestory/v1/character/list");
50	const getScheduler = (ocid, date) =>
51	  nx("/maplestory/v1/scheduler/character-state", date ? { ocid, date } : { ocid });
52	
53	async function getCombatPower(ocid) {
54	  const stat = await nx("/maplestory/v1/character/stat", { ocid });
55	  const row = (stat.final_stat || []).find((s) => s.stat_name === "전투력");
56	  return row ? Number(row.stat_value) : null;
57	}
58	
59	// ---------- 장비 구성 해시 ----------
60	// 전투력에 영향을 주는 필드만 추려서 해시. 외형/캐시 요소는 제외해
61	// 코디 변경으로 무효화가 오발동하지 않게 한다.
62	
63	function normalizeItem(it) {
64	  return {
65	    slot: it.item_equipment_slot,
66	    name: it.item_name,
67	    star: it.starforce ?? "0",
68	    total: it.item_total_option ?? null, // 주문서+스타포스 반영 최종 수치
69	    pot: [it.potential_option_grade, it.potential_option_1, it.potential_option_2, it.potential_option_3],
70	    add: [it.additional_potential_option_grade, it.additional_potential_option_1, it.additional_potential_option_2, it.additional_potential_option_3],
71	    soul: it.soul_name ?? null,
72	  };
73	}
74	
75	function hashItemList(list) {
76	  const norm = (list || [])
77	    .map(normalizeItem)
78	    .sort((a, b) => (a.slot > b.slot ? 1 : -1));
79	  return crypto.createHash("sha1").update(JSON.stringify(norm)).digest("hex").slice(0, 16);
80	}
81	
82	/** 착용 + 프리셋 1/2/3 각각의 구성 해시 */
83	function setupHashes(equip) {
84	  return {
85	    equipped: hashItemList(equip.item_equipment),
86	    p1: hashItemList(equip.item_equipment_preset_1),
87	    p2: hashItemList(equip.item_equipment_preset_2),
88	    p3: hashItemList(equip.item_equipment_preset_3),
89	  };
90	}
91	
92	// ---------- 결정석 가격표 ----------
93	// boss_crystal_prices.json: prices[보스명][난이도] = {old,new,new_from} | {price} | null
94	// 보스명·난이도는 스케줄러 API의 content_name / difficulty 값과 동일하게 맞춘다.
95	
96	const PRICE_FILE = path.join(__dirname, "boss_crystal_prices.json");
97	const PRICE_TABLE = (() => {
98	  try { return JSON.parse(fs.readFileSync(PRICE_FILE, "utf8")); } catch { return { _meta: {}, prices: {} }; }
99	})();
100	
101	/** 기준일(YYYY-MM-DD)에 유효한 결정석 가격. 미확인이면 null. */
102	function crystalPrice(bossName, difficulty, dateISO) {
103	  const entry = PRICE_TABLE.prices?.[bossName]?.[difficulty];
104	  if (!entry) return null;
105	  if ("price" in entry) return entry.price;
106	  if (entry.new_from && dateISO >= entry.new_from) return entry.new;
107	  return entry.old ?? null;
108	}
109	
110	// ---------- 로그 저장소 ----------
111	// { [ocid]: { name, entries: [{ts, power}],
112	//             best: { power, ts, setupHash } | null } }
113	
114	function loadLog() {
115	  try { return JSON.parse(fs.readFileSync(LOG_FILE, "utf8")); } catch { return {}; }
116	}
117	function saveLog(log) {
118	  fs.writeFileSync(LOG_FILE, JSON.stringify(log, null, 2));
119	}
120	
121	// ---------- 대표 전투력 갱신 로직 (핵심) ----------
122	
123	function updateBest(rec, power, hashes) {
124	  const now = new Date().toISOString();
125	  let note = null;
126	
127	  // 1) 기존 최대치의 세팅이 아직 존재하는지 검사
128	  if (rec.best) {
129	    const alive = Object.values(hashes).includes(rec.best.setupHash);
130	    if (!alive) {
131	      note = `세팅 변경 감지 → 기존 최대치 ${rec.best.power.toLocaleString()} 무효화, 현재 값으로 재설정`;
132	      rec.best = null;
133	    }
134	  }
135	
136	  // 2) 최대치 갱신 (무효화됐다면 현재 관측값이 새 기준이 됨)
137	  if (!rec.best || power > rec.best.power) {
138	    rec.best = { power, ts: now, setupHash: hashes.equipped };
139	    if (!note) note = "최대 전투력 갱신";
140	  }
141	
142	  rec.entries.push({ ts: now, power });
143	  return note;
144	}
145	
146	// ---------- 출력 유틸 ----------
147	
148	function fmtPower(n) {
149	  if (n == null) return "-";
150	  if (n >= 100_000_000) {
151	    const eok = Math.floor(n / 100_000_000);
152	    const man = Math.floor((n % 100_000_000) / 10_000);
153	    return man > 0 ? `${eok}억 ${man}만` : `${eok}억`;
154	  }
155	  if (n >= 10_000) return `${Math.floor(n / 10_000)}만`;
156	  return String(n);
157	}
158	
159	// ---------- 커맨드 ----------
160	
161	async function cmdChar(name) {
162	  const ocid = await getOcid(name);
163	  const [basic, power, equip] = await Promise.all([
164	    getBasic(ocid), getCombatPower(ocid), getEquipment(ocid),
165	  ]);
166	  const hashes = setupHashes(equip);
167	
168	  const log = loadLog();
169	  if (!log[ocid]) log[ocid] = { name: basic.character_name, entries: [], best: null };
170	  const rec = log[ocid];
171	  rec.name = basic.character_name;
172	  const note = updateBest(rec, power, hashes);
173	  saveLog(log);
174	
175	  const wearingBest = hashes.equipped === rec.best.setupHash;
176	  console.log(`\n${basic.character_name}  (${basic.world_name} · ${basic.character_class} · Lv.${basic.character_level})`);
177	  console.log(`  대표 전투력 : ${fmtPower(rec.best.power)} (${rec.best.ts.slice(0, 10)} 기준)`);
178	  console.log(`  현재 측정값 : ${fmtPower(power)}${wearingBest ? "" : "  ※ 대표값과 다른 세팅 착용 중"}`);
179	  if (note) console.log(`  변경 사항   : ${note}`);
180	  console.log(`  maplescouter: https://maplescouter.com/ko/result?name=${encodeURIComponent(basic.character_name)}`);
181	  console.log("");
182	}
183	
184	async function cmdLog(name) {
185	  const log = loadLog();
186	  const rec = Object.values(log).find((c) => c.name === name);
187	  if (!rec) return console.log(`기록 없음: ${name} — 먼저 'char ${name}' 로 조회하세요.`);
188	  console.log(`\n${rec.name} — 대표 전투력 ${fmtPower(rec.best?.power)} (${rec.best?.ts.slice(0, 10)} 기준)`);
189	  for (const e of rec.entries.slice(-10)) {
190	    console.log(`  ${e.ts.slice(0, 16).replace("T", " ")}  ${fmtPower(e.power)}`);
191	  }
192	  console.log("");
193	}
194	
195	async function cmdSched(name, date) {
196	  const ocid = await getOcid(name);
197	  let s;
198	  try {
199	    s = await getScheduler(ocid, date);
200	  } catch (e) {
201	    // date 지정 조회는 해당 날짜에 캐릭터 기록이 없으면 OPENAPI00004(400)로 응답함 (실측).
