203	      return console.log(`${name}: ${date} 스케줄러 기록 없음 (해당 날짜 미접속, 또는 조회 범위(어제~13일 전) 밖)`);
204	    }
205	    throw e;
206	  }
207	  if (!s) return console.log("스케줄러 데이터 없음 (최근 14일 내 접속 기록이 없을 수 있음)");
208	
209	  // 가격 기준일: date 지정 조회면 그 날, 실시간이면 오늘
